1	//! The work run's record (design v1, `docs/work-mode.md`): the `<NN>-<provider>-<model>`
2	//! directory under `<collab>/<task>/work/`, its `run.json`, the git diff c3 computes around
3	//! the child, and the summary parsed from the child's event stream.
4	
5	use std::collections::BTreeMap;
6	use std::path::{Path, PathBuf};
7	
8	use serde::{Deserialize, Serialize};
9	use serde_json::Value;
10	
11	/// The quota block of a work run that hit a provider usage limit (`docs/work-mode.md`, quota
12	/// resume): the limit wording, when the window resets, when `c3 work` will resume the child, how
13	/// many times it already has, and whether the resume cap is spent.
14	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
15	pub struct Quota {
16	    /// The usage-limit wording (the engine's `quota_evidence`, never a secret).
17	    pub text: String,
18	    /// When the provider says the window resets (RFC3339 UTC), or `null` when it said none.
19	    #[serde(default)]
20	    pub reset_at: Option<String>,
21	    /// When `c3 work` resumes the child: `reset_at` + 60 s when known, else now + the quota window.
22	    pub resume_at: String,
23	    /// How many times this run has already been resumed.
24	    #[serde(default)]
25	    pub resumes: i64,
26	    /// The resume cap is spent (`resumes` reached `--max-resumes`): the run needs a human.
27	    #[serde(default)]
28	    pub exhausted: bool,
29	}
30	
31	/// `run.json` of one work run. Written `running` before the child starts, made final
32	/// (`done` | `died` | `timeout` | `refused` | `quota`, or `waiting_quota` while a detached run's
33	/// alarm sleeps) when it ends; `args` carries the background's options wire of a detached run
34	/// (taken by the background, never a secret).
35	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
36	pub struct RunRecord {
37	    /// The record directory's name (`NN-provider-model`).
38	    pub id: String,
39	    pub task: String,
40	    pub seq: i64,
41	    pub provider: String,
42	    pub model: String,
43	    pub engine: String,
44	    /// The argv after the launcher (no secrets travel in argv).
45	    pub argv: Vec<String>,
46	    /// The host-marker NAMES scrubbed from the child (never a value).
47	    pub child_env_scrubbed: Vec<String>,
48	    pub started: String,
49	    #[serde(default)]
50	    pub ended: Option<String>,
51	    #[serde(default)]
52	    pub exit_code: Option<i64>,
53	    /// `running` while live, `waiting_quota` while a detached run's alarm sleeps, else `done` |
54	    /// `died` | `timeout` | `refused` | `quota`.
55	    pub status: String,
56	    /// The child session id (`--session-id` of the first launch): the session a quota resume
57	    /// continues with `--resume`.
58	    #[serde(default)]
59	    pub session_id: String,
60	    /// The quota block when the run hit a usage limit (status `quota` or `waiting_quota`).
61	    #[serde(default)]
62	    pub quota: Option<Quota>,
63	    #[serde(default)]
64	    pub turns: Option<i64>,
65	    /// Tool name -> how often the assistant called it.
66	    #[serde(default)]
67	    pub tool_calls: BTreeMap<String, i64>,
68	    #[serde(default)]
69	    pub files_changed: Vec<String>,
70	    /// The result event's usage/cost when present.
71	    #[serde(default)]
72	    pub usage: Option<Value>,
73	    /// The run's own timeout (the `--wait` default of a detached run).
74	    #[serde(default)]
75	    pub timeout_sec: i64,
76	    /// The OWNING process's pid (the c3 process that spawned the child: a foreground run's own
77	    /// pid, written before the child starts; a detached run's background pid). While a run is
78	    /// `running`/`waiting_quota` this pid with [`RunRecord::pid_start`] is the liveness owner.
79	    #[serde(default)]
80	    pub pid: Option<i64>,
81	    /// (0.2.4, F89-1) The owning process's start time (the liveness anchor against pid reuse;
82	    /// `""` when it could not be read). `pid` + `pid_start` together prove the owner is still
83	    /// alive; [`START_GRACE_SEC`] only covers the window before any pid is written.
84	    #[serde(default)]
85	    pub pid_start: String,
86	    /// (0.2.4, F89-2) The attempt number of the current claim: `0` the first launch, `n` the
87	    /// n-th resume. Written under the task admission lock when the record is claimed `running`.
88	    #[serde(default)]
89	    pub attempt: i64,
90	    /// (0.2.4, F89-6) The effective resume cap persisted at the first run, reused by a later plain
91	    /// `--resume` (an explicit `--max-resumes` still overrides). `0` = the default (3).
92	    #[serde(default)]
93	    pub max_resumes: i64,
94	    /// (0.2.4, F89-6) The effective quota window (seconds) persisted at the first run, reused by a
95	    /// later plain `--resume`. `0` = the default (18000 = 5 h).
96	    #[serde(default)]
97	    pub quota_window_sec: i64,
98	    /// (0.2.4, F89-4) Whether the run was admitted `--unrestricted` (allow-list grammar lifted;
99	    /// muse's `--disable-sandbox` permitted).
100	    #[serde(default)]
101	    pub unrestricted: bool,
102	    /// (0.2.4, F89-4) A one-line description of the effective permission boundary (the allow list
103	    /// applies only to claude; codex is `workspace-write`; muse is `--disable-sandbox`).
104	    #[serde(default)]
105	    pub permission: String,
106	    /// (0.2.4, F89-3/F89-8) The terminal error text when the run ended `died`/`artifact_error`
107	    /// (the artifact write failure, or `no terminal event`); `""` otherwise.
108	    #[serde(default)]
109	    pub error: String,
110	    /// The background's options wire (a detached run's `running` record only).
111	    #[serde(default)]
112	    pub args: Option<String>,
113	    /// The `git status --short` baseline captured before the FIRST launch: a quota resume diffs
114	    /// the whole run against it, so `diff.txt` and `files_changed` stay stable across resumes.
115	    #[serde(default)]
116	    pub baseline: Vec<String>,
117	    /// (0.2.4, F89-7) The content hash (`git hash-object`) of every path dirty at the baseline,
118	    /// captured before the FIRST launch: `files_changed` lists a path whose content now differs
119	    /// from its baseline hash, so a pre-dirty file the worker edited further is reported.
120	    #[serde(default)]
121	    pub baseline_hashes: BTreeMap<String, String>,
122	    /// (0.2.5) `"tests"` for a run started `--role tests` (it writes tests for another author's
123	    /// change); `""` for an ordinary run.
124	    #[serde(default)]
125	    pub role: String,
126	    /// (0.2.5) The work run whose change a `--role tests` run tests (`--of`); `""` when it tests
127	    /// the working tree's change against HEAD (the coordinator's own code).
128	    #[serde(default)]
129	    pub of: String,
130	    /// (0.2.5) The globs the run may change (`--scope`, plus the test-path defaults of a
131	    /// `--role tests` run); empty = no scope check.
132	    #[serde(default)]
133	    pub scope: Vec<String>,
134	    /// (0.2.5) The changed files outside `scope` - a post-hoc check, not a containment: no worker
135	    /// engine can refuse an edit by path before it happens.
136	    #[serde(default)]
137	    pub scope_violations: Vec<String>,
138	}
