140	impl RunRecord {
141	    pub fn to_bytes(&self) -> Result<Vec<u8>, String> {
142	        serde_json::to_vec_pretty(self).map_err(|e| e.to_string())
143	    }
144	}
145	
146	/// Write `run.json` (atomic replace).
147	pub fn write_record(dir: &Path, rec: &RunRecord) -> Result<(), String> {
148	    let bytes = rec.to_bytes()?;
149	    c3_core::store::write_text_atomic(&dir.join("run.json"), &bytes).map_err(|e| e.to_string())
150	}
151	
152	/// Read one `run.json`. (0.2.4, F91-2) FAIL CLOSED: only a confirmed `NotFound` is absence
153	/// (`Ok(None)`); any other read error, or a parse failure, is `Err` (the message names the
154	/// directory, never the contents) so admission refuses rather than treats an unreadable record as
155	/// an absent run.
156	pub fn read_record(dir: &Path) -> Result<Option<RunRecord>, String> {
157	    // (0.2.4, F93-1) A PURE fallible reader — it NEVER writes. The dead-owner → `died` transition
158	    // is a separate, locked operation ([`recover_dead_run`], via [`read_for_display`]); a status
159	    // reader must not race the admission lock by rewriting a record it holds only a stale snapshot
160	    // of. Liveness is decided by [`is_live`] at the call site (so a dead pending record never counts
161	    // as a live run); only the display path persists `died`.
162	    let p = dir.join("run.json");
163	    let bytes = match std::fs::read(&p) {
164	        Ok(b) => b,
165	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
166	        Err(e) => return Err(format!("{} could not be read ({e})", p.display())),
167	    };
168	    let rec: RunRecord = serde_json::from_slice(&bytes)
169	        .map_err(|e| format!("{} does not parse: {e}", p.display()))?;
170	    Ok(Some(rec))
171	}
172	
173	/// (0.2.4, F93-1) Whether two records are the SAME generation of the same run: the owning pid, its
174	/// start time and the attempt number all match. A recovery write only proceeds when the record on
175	/// disk is still the generation the reader snapshotted (so it cannot clobber a newer claim).
176	fn same_generation(a: &RunRecord, b: &RunRecord) -> bool {
177	    a.pid == b.pid && a.pid_start == b.pid_start && a.attempt == b.attempt
178	}
179	
180	/// (0.2.4, F93-1) TEST-ONLY recovery barrier (honoured only in test mode): when
181	/// `CODEX_CONSULT_TEST_WORK_RECOVERY_BARRIER` names a path, wait (bounded) until it exists — the
182	/// acceptance test interposes a competing resume claim between the status snapshot and the locked
183	/// recovery re-read.
184	fn test_recovery_barrier() {
185	    if let Some(gate) = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_WORK_RECOVERY_BARRIER") {
186	        let gate = PathBuf::from(gate);
187	        for _ in 0..600 {
188	            if gate.exists() {
189	                return;
190	            }
191	            std::thread::sleep(std::time::Duration::from_millis(100));
192	        }
193	    }
194	}
195	
196	/// (0.2.4, F93-1) Persist the `died` transition for a pending record whose owner looks dead, UNDER
197	/// the task admission lock. Re-reads the CURRENT record and writes `died` ONLY when it is still the
198	/// same generation as `snapshot` AND still pending AND its owner is still dead — so a resume that
199	/// claimed the record (new pid/attempt) in the meantime is never overwritten. Returns the current
200	/// record after the attempt and PROPAGATES a write failure.
201	pub fn recover_dead_run(
202	    work_root: &Path,
203	    dir: &Path,
204	    snapshot: &RunRecord,
205	) -> Result<Option<RunRecord>, String> {
206	    let _lock = admission_lock(work_root)?;
207	    let mut rec = match read_record(dir)? {
208	        Some(r) => r,
209	        None => return Ok(None),
210	    };
211	    if same_generation(&rec, snapshot) && is_pending(&rec.status) && !is_live(&rec) {
212	        rec.status = "died".into();
213	        rec.ended = Some(chrono::Utc::now().to_rfc3339());
214	        rec.args = None;
215	        write_record(dir, &rec)?;
216	    }
217	    Ok(Some(rec))
218	}
219	
220	/// (0.2.4, F93-1) Read a record for the DISPLAY path (`--status`/`--wait`/the resume listing): a
221	/// pure read, then — when the owner looks dead — the `died` transition done UNDER the admission
222	/// lock via [`recover_dead_run`] (never an unlocked write), with its result and errors surfaced.
223	pub fn read_for_display(work_root: &Path, dir: &Path) -> Result<Option<RunRecord>, String> {
224	    let rec = match read_record(dir)? {
225	        Some(r) => r,
226	        None => return Ok(None),
227	    };
228	    if is_pending(&rec.status) && !is_live(&rec) {
229	        test_recovery_barrier();
230	        return recover_dead_run(work_root, dir, &rec);
231	    }
232	    Ok(Some(rec))
233	}
234	
235	/// How long a pending record may go without a reported pid before it counts as dead
236	/// (the background reports its pid within its first second).
237	const START_GRACE_SEC: i64 = 120;
238	
239	/// Whether a status means the run's background is still supposed to be alive: `running`, or
240	/// `waiting_quota` while a detached run's alarm sleeps until the quota window resets.
241	pub fn is_pending(status: &str) -> bool {
242	    status == "running" || status == "waiting_quota"
243	}
244	
245	/// Whether a pending record's background is alive: its reported pid exists, or no pid was
246	/// reported yet and the record is younger than [`START_GRACE_SEC`]. Anything else is dead.
247	pub fn is_live(rec: &RunRecord) -> bool {
248	    if !is_pending(&rec.status) {
249	        return false;
250	    }
251	    match rec.pid {
252	        Some(pid) if pid > 0 => crate::liveness::proc::pid_alive(pid as u32, &rec.pid_start),
253	        _ => match chrono::DateTime::parse_from_rfc3339(&rec.started) {
254	            Ok(t) => {
255	                (chrono::Utc::now() - t.with_timezone(&chrono::Utc)).num_seconds() < START_GRACE_SEC
256	            }
257	            Err(_) => false,
258	        },
259	    }
260	}
261	
262	/// Every work run directory of a task's `work/` root, by sequence. (0.2.4, F91-2) FAIL CLOSED: a
263	/// missing work root is `Ok([])`, but an enumeration or entry error is `Err`; a directory with the
264	/// `NN-` prefix is a candidate when its `run.json` path EXISTS in any form (file, directory or
265	/// otherwise), so an unreadable or replaced record is NOT silently dropped — `read_record` then
266	/// reports the inspection error.
267	pub fn run_dirs(work_root: &Path) -> Result<Vec<(i64, PathBuf)>, String> {
268	    let mut out: Vec<(i64, PathBuf)> = Vec::new();
269	    let rd = match std::fs::read_dir(work_root) {
270	        Ok(rd) => rd,
271	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(out),
272	        Err(e) => {
273	            return Err(format!(
274	                "could not enumerate the work directory {} ({e})",
275	                work_root.display()
276	            ))
277	        }
278	    };
279	    for entry in rd {
280	        let entry = entry.map_err(|e| {
281	            format!(
282	                "could not read an entry of the work directory {} ({e})",
283	                work_root.display()
284	            )
285	        })?;
286	        let name = entry.file_name().to_string_lossy().to_string();
287	        let first = name.split('-').next().unwrap_or("");
288	        if first.is_empty() || !first.chars().all(|c| c.is_ascii_digit()) {
289	            continue;
290	        }
291	        let seq: i64 = first.parse().unwrap_or(0);
292	        if seq <= 0 {
293	            continue;
294	        }
295	        let run_json = entry.path().join("run.json");
296	        match run_json.try_exists() {
297	            Ok(true) => out.push((seq, entry.path())),
298	            Ok(false) => continue, // a directory with no run.json is not a run
299	            Err(e) => return Err(format!("could not inspect {} ({e})", run_json.display())),
300	        }
301	    }
302	    out.sort_by_key(|(seq, _)| *seq);
303	    Ok(out)
304	}
305	
306	/// Whether a live work run exists for the task (a `running` or `waiting_quota` record): its id,
307	/// or `None`. (0.2.4, F91-2) `Err` when any candidate record cannot be inspected.
308	pub fn live_run(work_root: &Path) -> Result<Option<String>, String> {
309	    for (_, dir) in run_dirs(work_root)? {
310	        if let Some(r) = read_record(&dir)? {
311	            // (0.2.4, F93-1) read_record no longer rewrites a ghost, so liveness is checked here:
312	            // a pending record whose owner is dead does NOT count as a live run.
313	            if is_pending(&r.status) && is_live(&r) {
314	                return Ok(Some(r.id));
315	            }
316	        }
317	    }
318	    Ok(None)
319	}
320	
321	/// (0.2.4, F89-2) The id of any LIVE run of the task other than the one at `exclude`, or `None`.
322	/// Used under the admission lock so a start/resume/alarm refuses while another run is alive.
323	/// (0.2.4, F91-2) `Err` when any candidate record cannot be inspected.
324	pub fn other_live_run(work_root: &Path, exclude: &Path) -> Result<Option<String>, String> {
325	    for (_, dir) in run_dirs(work_root)? {
326	        if dir == exclude {
327	            continue;
328	        }
329	        if let Some(r) = read_record(&dir)? {
330	            if is_pending(&r.status) && is_live(&r) {
331	                return Ok(Some(r.id));
332	            }
333	        }
334	    }
335	    Ok(None)
336	}
337	
338	/// (0.2.4, F89-1/F89-2) This c3 process's own pid and start time: the owner written into a
339	/// record when it is claimed `running` before the child is spawned.
340	pub fn self_owner() -> (i64, String) {
341	    let pid = std::process::id();
342	    (
343	        pid as i64,
344	        crate::liveness::proc::process_start_iso(pid).unwrap_or_default(),
345	    )
346	}
347	
348	/// (0.2.4, F89-2) The task-level admission lock file (held only across the claim's
349	/// check-and-write, released on drop or when the process dies).
350	pub const ADMISSION_LOCK: &str = ".admission.lock";
351	
352	/// (0.2.4, F89-2) An exclusive OS lock on the task's admission-lock file, released when dropped
353	/// (or when the process dies). The same advisory-lock mechanism the telemetry spool uses.
354	pub struct AdmissionLock {
355	    _file: std::fs::File,
356	}
357	
358	/// (0.2.4, F89-2) Take the task's admission lock (one claim at a time across starts, resumes and
359	/// the detached alarm), waiting at most 10 s. The guard releases the lock when dropped.
360	pub fn admission_lock(work_root: &Path) -> Result<AdmissionLock, String> {
361	    let _ = std::fs::create_dir_all(work_root);
362	    let path = work_root.join(ADMISSION_LOCK);
363	    let file = std::fs::OpenOptions::new()
364	        .read(true)
365	        .write(true)
366	        .create(true)
367	        .truncate(false)
368	        .open(&path)
369	        .map_err(|e| format!("could not open the task admission lock ({e})"))?;
370	    let started = std::time::Instant::now();
371	    loop {
372	        match file.try_lock() {
373	            Ok(()) => return Ok(AdmissionLock { _file: file }),
374	            Err(std::fs::TryLockError::WouldBlock) => {
375	                if started.elapsed() >= std::time::Duration::from_secs(10) {
376	                    return Err(
377	                        "the task's admission lock stayed busy (another c3 work is admitting a run)"
378	                            .into(),
379	                    );
380	                }
381	                std::thread::sleep(std::time::Duration::from_millis(25));
382	            }
383	            Err(std::fs::TryLockError::Error(e)) => {
384	                return Err(format!("could not take the task admission lock ({e})"))
385	            }
386	        }
387	    }
388	}
389	
390	/// A directory-name-safe form of a provider label or model id: everything outside
391	/// `[A-Za-z0-9._-]` becomes `-` (never empty).
392	fn dir_part(s: &str) -> String {
393	    let mut out: String = s
394	        .chars()
395	        .map(|c| {
396	            if c.is_ascii_alphanumeric() || c == '.' || c == '_' || c == '-' {
397	                c
398	            } else {
399	                '-'
400	            }
401	        })
402	        .collect();
403	    out.truncate(60);
404	    if out.is_empty() {
405	        out.push('x');
406	    }
407	    out
408	}
409	
410	/// The next record directory of a task: `<work>/<NN>-<provider>-<model>` with NN the next
411	/// 2-digit sequence (never one that exists).
412	pub fn allocate(
413	    work_root: &Path,
414	    provider: &str,
415	    model: &str,
416	) -> Result<(String, i64, PathBuf), String> {
417	    let next = run_dirs(work_root)?
418	        .iter()
419	        .map(|(seq, _)| *seq)
420	        .max()
421	        .unwrap_or(0)
422	        + 1;
423	    for seq in next..(next + 50) {
424	        let id = format!("{seq:02}-{}-{}", dir_part(provider), dir_part(model));
425	        let dir = work_root.join(&id);
426	        if !dir.exists() {
427	            std::fs::create_dir_all(&dir).map_err(|e| {
428	                format!(
429	                    "could not create the work record directory '{}' ({e})",
430	                    dir.display()
431	                )
432	            })?;
433	            return Ok((id, seq, dir));
434	        }
435	    }
436	    Err(format!(
437	        "no free work record directory under '{}' (50 tried); remove old work runs",
438	        work_root.display()
439	    ))
440	}
