442	// ------------------------------------------------------------------ the git diff (c3 runs git, not the worker)
443	
444	/// One read-only git command's stdout lines (empty on any failure).
445	fn git_lines(repo: &Path, args: &[&str]) -> Vec<String> {
446	    std::process::Command::new("git")
447	        .arg("-C")
448	        .arg(repo)
449	        .args(args)
450	        .output()
451	        .map(|o| {
452	            if o.status.success() {
453	                String::from_utf8_lossy(&o.stdout)
454	                    .lines()
455	                    .map(|l| l.to_string())
456	                    .collect()
457	            } else {
458	                Vec::new()
459	            }
460	        })
461	        .unwrap_or_default()
462	}
463	
464	/// `git status --short` lines (the baseline before the run, the state after it).
465	pub fn status_short(repo: &Path) -> Vec<String> {
466	    git_lines(repo, &["status", "--short"])
467	}
468	
469	/// `git diff --stat` lines after the run.
470	pub fn diff_stat(repo: &Path) -> Vec<String> {
471	    git_lines(repo, &["diff", "--stat"])
472	}
473	
474	/// The path a `git status --short` line names (the `R  old -> new` form names the new path).
475	fn path_of_status_line(line: &str) -> String {
476	    let p = line.get(3..).unwrap_or("").trim();
477	    match p.split_once(" -> ") {
478	        Some((_, new)) => new.trim().to_string(),
479	        None => p.to_string(),
480	    }
481	}
482	
483	/// (0.2.4, F89-7) The content hash of a working-tree path (`git hash-object`), `"<absent>"` when
484	/// the file does not exist (a deletion), `""` when git cannot hash it.
485	pub fn hash_of(repo: &Path, path: &str) -> String {
486	    if !repo.join(path).exists() {
487	        return "<absent>".to_string();
488	    }
489	    git_lines(repo, &["hash-object", "--", path])
490	        .into_iter()
491	        .next()
492	        .unwrap_or_default()
493	}
494	
495	/// (0.2.4, F89-7) The content hash of every path dirty at the baseline (`git status --short`
496	/// before the run). `files_changed` compares against this so a path already dirty but edited
497	/// further by the worker is reported, and one left untouched is not.
498	///
499	/// (0.2.5) The baseline content is also WRITTEN to git's object store (`hash-object -w`; a loose
500	/// object, never a commit or a ref), so `patch.diff` can show what the worker changed in a file
501	/// that was already dirty.
502	pub fn baseline_hashes(repo: &Path, before: &[String]) -> BTreeMap<String, String> {
503	    let mut m = BTreeMap::new();
504	    for line in before {
505	        let p = path_of_status_line(line);
506	        if !p.is_empty() {
507	            let h = if repo.join(&p).is_file() {
508	                store_blob(repo, &p).unwrap_or_default()
509	            } else {
510	                hash_of(repo, &p)
511	            };
512	            m.insert(p, h);
513	        }
514	    }
515	    m
516	}
