518	/// (0.2.4, F89-7) The files the run changed, by CONTENT IDENTITY: every path dirty after the run
519	/// whose current content hash differs from its baseline hash (a new/untracked path has no baseline
520	/// hash, so it is listed; a pre-dirty path the worker edited further differs, so it is listed; a
521	/// pre-dirty path left untouched matches, so it is not). After-order, deduplicated.
522	pub fn files_changed(
523	    baseline_hashes: &BTreeMap<String, String>,
524	    after: &[String],
525	    repo: &Path,
526	) -> Vec<String> {
527	    let mut out: Vec<String> = Vec::new();
528	    for line in after {
529	        let p = path_of_status_line(line);
530	        if p.is_empty() || out.contains(&p) {
531	            continue;
532	        }
533	        let now = hash_of(repo, &p);
534	        match baseline_hashes.get(&p) {
535	            Some(b) if *b == now => {} // dirty before and still the same content: not the worker's
536	            _ => out.push(p),
537	        }
538	    }
539	    out
540	}
