542	/// The stdout of a git command that succeeded; `None` otherwise.
543	fn git_raw(repo: &Path, args: &[&str]) -> Option<String> {
544	    let o = std::process::Command::new("git")
545	        .arg("-C")
546	        .arg(repo)
547	        .args(args)
548	        .stdin(std::process::Stdio::null())
549	        .output()
550	        .ok()?;
551	    o.status
552	        .success()
553	        .then(|| String::from_utf8_lossy(&o.stdout).to_string())
554	}
