556	/// (0.2.5) Write a working-tree file's content to the object store; its blob id.
557	fn store_blob(repo: &Path, path: &str) -> Option<String> {
558	    git_raw(repo, &["hash-object", "-w", "--", path])
559	        .map(|s| s.trim().to_string())
560	        .filter(|s| !s.is_empty())
561	}
562	
563	/// (0.2.5) The empty blob, written so a diff against it (a new or a deleted file) resolves.
564	fn empty_blob(repo: &Path) -> Option<String> {
565	    git_raw(repo, &["hash-object", "-w", "--stdin"])
566	        .map(|s| s.trim().to_string())
567	        .filter(|s| !s.is_empty())
568	}
569	
570	/// (0.2.5) The blob of `path` at HEAD; `None` when HEAD has no such path.
571	fn head_blob(repo: &Path, path: &str) -> Option<String> {
572	    git_raw(
573	        repo,
574	        &["rev-parse", "--verify", "-q", &format!("HEAD:{path}")],
575	    )
576	    .map(|s| s.trim().to_string())
577	    .filter(|s| !s.is_empty())
578	}
