580	/// (0.2.5) A `git status --short` path that names an untracked DIRECTORY (`?? dir/`) stands for
581	/// every untracked file under it.
582	fn expand_path(repo: &Path, p: &str) -> Vec<String> {
583	    if p.ends_with('/') {
584	        git_lines(
585	            repo,
586	            &["ls-files", "--others", "--exclude-standard", "--", p],
587	        )
588	    } else {
589	        vec![p.to_string()]
590	    }
591	}
