593	/// (0.2.5) The unified diff of one file from the blob `before` (`None` = it did not exist) to its
594	/// working-tree content (absent = deleted); `""` when nothing changed. The hunks are git's
595	/// (`git diff <blob> <blob>`); the header names the path, not the blob ids.
596	pub fn file_patch(repo: &Path, path: &str, before: Option<&str>) -> String {
597	    let after = if repo.join(path).is_file() {
598	        store_blob(repo, path)
599	    } else {
600	        None
601	    };
602	    if before.is_none() && after.is_none() || before == after.as_deref() {
603	        return String::new();
604	    }
605	    let Some(empty) = empty_blob(repo) else {
606	        return String::new();
607	    };
608	    let a = before.unwrap_or(&empty);
609	    let b = after.as_deref().unwrap_or(&empty);
610	    let Some(out) = git_raw(repo, &["diff", "--no-color", "--no-ext-diff", a, b]) else {
611	        return String::new();
612	    };
613	    let from = if before.is_some() {
614	        format!("a/{path}")
615	    } else {
616	        "/dev/null".to_string()
617	    };
618	    let to = if after.is_some() {
619	        format!("b/{path}")
620	    } else {
621	        "/dev/null".to_string()
622	    };
623	    let mut text = format!("diff --git a/{path} b/{path}\n--- {from}\n+++ {to}\n");
624	    let mut body = false;
625	    for line in out.lines() {
626	        if line.starts_with("Binary files ") {
627	            text.push_str(&format!("Binary files {from} and {to} differ\n"));
628	            break;
629	        }
630	        body |= line.starts_with("@@");
631	        if body {
632	            text.push_str(line);
633	            text.push('\n');
634	        }
635	    }
636	    text
637	}
