639	/// (0.2.5) `patch.diff` of a work run: every file it changed, from its baseline content (the
640	/// stored blob of a pre-dirty path, else HEAD's, else nothing) to its content now.
641	pub fn run_patch(
642	    repo: &Path,
643	    baseline_hashes: &BTreeMap<String, String>,
644	    changed: &[String],
645	) -> String {
646	    let mut out = String::new();
647	    for p in changed {
648	        for f in expand_path(repo, p) {
649	            let before = match baseline_hashes.get(&f).map(String::as_str) {
650	                Some("<absent>") => None,
651	                Some(h) if !h.is_empty() => Some(h.to_string()),
652	                _ => head_blob(repo, &f),
653	            };
654	            out.push_str(&file_patch(repo, &f, before.as_deref()));
655	        }
656	    }
657	    out
658	}
