660	/// (0.2.5) The working tree's change against HEAD (the change a `--role tests` run without `--of`
661	/// tests), every path under `skip` (the collab directory) left out.
662	pub fn worktree_patch(repo: &Path, skip: &str) -> String {
663	    let mut out = String::new();
664	    for line in status_short(repo) {
665	        for f in expand_path(repo, &path_of_status_line(&line)) {
666	            if !skip.is_empty() && f.starts_with(skip) {
667	                continue;
668	            }
669	            let before = head_blob(repo, &f);
670	            out.push_str(&file_patch(repo, &f, before.as_deref()));
671	        }
672	    }
673	    out
674	}
