676	/// (0.2.5) The changed files no `scope` glob matches, every path under `skip` (the collab
677	/// directory: the run's own record) left out. An empty scope checks nothing.
678	pub fn scope_violations(
679	    repo: &Path,
680	    scope: &[String],
681	    changed: &[String],
682	    skip: &str,
683	) -> Vec<String> {
684	    if scope.is_empty() {
685	        return Vec::new();
686	    }
687	    let mut b = globset::GlobSetBuilder::new();
688	    for g in scope {
689	        if let Ok(glob) = globset::Glob::new(g) {
690	            b.add(glob);
691	        }
692	    }
693	    let Ok(set) = b.build() else {
694	        return Vec::new();
695	    };
696	    changed
697	        .iter()
698	        .flat_map(|p| expand_path(repo, p))
699	        .filter(|p| skip.is_empty() || !p.starts_with(skip))
700	        .filter(|p| !set.is_match(p))
701	        .collect()
702	}
