704	/// `diff.txt`: the baseline, the after state and the diff stat.
705	pub fn diff_text(before: &[String], after: &[String], stat: &[String]) -> String {
706	    let block = |title: &str, lines: &[String]| -> String {
707	        if lines.is_empty() {
708	            format!("{title}: (empty)\n")
709	        } else {
710	            format!("{title}:\n{}\n", lines.join("\n"))
711	        }
712	    };
713	    format!(
714	        "{}\n{}\n{}",
715	        block("git status --short (before the run)", before),
716	        block("git status --short (after the run)", after),
717	        block("git diff --stat (after the run)", stat)
718	    )
719	}
