723	/// What c3 reads out of a work run's event stream (`events.jsonl`).
724	#[derive(Debug, Clone, Default)]
725	pub struct EventSummary {
726	    pub has_result: bool,
727	    /// The result event's `result` text (the report).
728	    pub result_text: String,
729	    pub is_error: bool,
730	    /// (0.2.4, F91-4) Affirmative success: a `result` event with `is_error` present AND false, and
731	    /// `subtype` either absent or `"success"`. A result that merely EXISTS (no `is_error`, or an
732	    /// error subtype) is NOT success.
733	    pub result_ok: bool,
734	    pub num_turns: Option<i64>,
735	    /// How many assistant events the stream holds (the `turns` fallback).
736	    pub assistant_count: i64,
737	    /// The last assistant text (the report of a run that died without a result).
738	    pub last_assistant_text: String,
739	    /// Tool name -> call count.
740	    pub tool_calls: BTreeMap<String, i64>,
741	    /// The result's `usage` merged with its `total_cost_usd` when present.
742	    pub usage: Option<Value>,
743	}
744	
745	/// (0.2.4, F89-5) The usage of a claude `result` event, rebuilt from an ALLOW LIST of numeric
746	/// counters — the token columns from the `usage` object plus `total_cost_usd`, `duration_ms` and
747	/// `num_turns` from the result. Any other field (a sentinel, a secret) is dropped. `None` when no
748	/// counter is present.
749	fn claude_usage(result_obj: &Value) -> Option<Value> {
750	    let mut map = serde_json::Map::new();
751	    if let Some(u) = result_obj.get("usage").filter(|v| v.is_object()) {
752	        for k in [
753	            "input_tokens",
754	            "output_tokens",
755	            "cache_creation_input_tokens",
756	            "cache_read_input_tokens",
757	        ] {
758	            if let Some(n) = u.get(k).and_then(|v| v.as_i64()) {
759	                map.insert(k.into(), Value::from(n));
760	            }
761	        }
762	    }
763	    for k in ["num_turns", "duration_ms"] {
764	        if let Some(n) = result_obj.get(k).and_then(|v| {
765	            v.as_i64()
766	                .or_else(|| v.as_str().and_then(|x| x.parse().ok()))
767	        }) {
768	            map.insert(k.into(), Value::from(n));
769	        }
770	    }
771	    if let Some(c) = result_obj.get("total_cost_usd").and_then(|v| {
772	        v.as_f64()
773	            .or_else(|| v.as_str().and_then(|x| x.parse().ok()))
774	    }) {
775	        map.insert("total_cost_usd".into(), Value::from(c));
776	    }
777	    (!map.is_empty()).then(|| Value::Object(map))
778	}
