780	/// Parse the event stream into an [`EventSummary`] (tolerant: a line that is not a JSON
781	/// object is skipped).
782	pub fn summarize_events(text: &str) -> EventSummary {
783	    let mut s = EventSummary::default();
784	    for line in text.split('\n') {
785	        let t = line.trim();
786	        if t.is_empty() || !t.starts_with('{') {
787	            continue;
788	        }
789	        let Ok(obj) = serde_json::from_str::<Value>(t) else {
790	            continue;
791	        };
792	        let ty = obj.get("type").and_then(|v| v.as_str()).unwrap_or("");
793	        if ty == "assistant" {
794	            s.assistant_count += 1;
795	            let content = obj
796	                .get("message")
797	                .and_then(|m| m.get("content"))
798	                .and_then(|c| c.as_array())
799	                .cloned()
800	                .unwrap_or_default();
801	            for b in content.iter().filter(|b| b.is_object()) {
802	                match b.get("type").and_then(|v| v.as_str()).unwrap_or("") {
803	                    "text" => {
804	                        let tx = b.get("text").and_then(|v| v.as_str()).unwrap_or("");
805	                        if !tx.trim().is_empty() {
806	                            s.last_assistant_text = tx.to_string();
807	                        }
808	                    }
809	                    "tool_use" => {
810	                        let name = b
811	                            .get("name")
812	                            .and_then(|v| v.as_str())
813	                            .unwrap_or("(unnamed)")
814	                            .to_string();
815	                        *s.tool_calls.entry(name).or_insert(0) += 1;
816	                    }
817	                    _ => {}
818	                }
819	            }
820	        } else if ty == "result" {
821	            s.has_result = true;
822	            s.result_text = obj
823	                .get("result")
824	                .and_then(|v| v.as_str())
825	                .unwrap_or("")
826	                .to_string();
827	            let is_error_field = obj.get("is_error").and_then(|v| v.as_bool());
828	            s.is_error = is_error_field == Some(true);
829	            let subtype = obj.get("subtype").and_then(|v| v.as_str()).unwrap_or("");
830	            // (0.2.4, F91-4) success needs affirmative evidence: is_error present and false, and
831	            // subtype success (or absent). A missing is_error is NOT success.
832	            s.result_ok =
833	                is_error_field == Some(false) && (subtype.is_empty() || subtype == "success");
834	            s.num_turns = obj.get("num_turns").and_then(|v| {
835	                v.as_i64()
836	                    .or_else(|| v.as_str().and_then(|x| x.parse().ok()))
837	            });
838	            // (0.2.4, F89-5) Rebuild usage from an ALLOW LIST of numeric counters — never clone the
839	            // whole usage object (a sentinel/secret in an extra field must not reach run.json).
840	            s.usage = claude_usage(&obj);
841	        }
842	    }
843	    s
844	}
