1008	            Some("01-zai-claude-glm-5.3")
1009	        );
1010	        rec.pid = None;
1011	        write_record(&dir, &rec).unwrap();
1012	        assert!(
1013	            live_run(&work).unwrap().is_none(),
1014	            "an old running record without a pid is dead"
1015	        );
1016	        // (F93-1) read_record is PURE: the ghost stays `running` on disk until the DISPLAY path
1017	        // persists `died` under the admission lock.
1018	        assert_eq!(read_record(&dir).unwrap().unwrap().status, "running");
1019	        assert_eq!(
1020	            read_for_display(&work, &dir).unwrap().unwrap().status,
1021	            "died"
1022	        );
1023	        assert_eq!(read_record(&dir).unwrap().unwrap().status, "died");
1024	        rec.pid = Some(std::process::id() as i64);
1025	        rec.status = "done".into();
1026	        write_record(&dir, &rec).unwrap();
1027	        assert!(live_run(&work).unwrap().is_none());
1028	        // the next sequence continues past it; the parts are sanitized
1029	        let (id2, seq2, dir2) = allocate(&work, "byteplus-claude", "deepseek/v4.1 flash").unwrap();
1030	        assert_eq!(seq2, 2);
1031	        assert!(id2.starts_with("02-byteplus-claude-deepseek-v4.1-flash"));
1032	        assert!(dir2.is_dir());
1033	        let _ = std::fs::remove_dir_all(&work);
1034	    }
1035	}
