162	/// The repo root, the collab root and the task directory of `o` (a relative `--collab-dir`
163	/// resolves against the repo root, as `c3 consult` resolves it). The task slug is checked
164	/// here: it names a directory under the collab root, so it may not escape it.
165	pub fn prepare_paths(o: &Options) -> Result<(PathBuf, PathBuf, PathBuf), String> {
166	    let task = o.task.trim();
167	    if task.is_empty() {
168	        return Err("--task is required (a slug of the collab dir: letters, digits, dot, dash, underscore).".into());
169	    }
170	    if task.len() > 64
171	        || task == "."
172	        || task == ".."
173	        || !task
174	            .chars()
175	            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
176	    {
177	        return Err(format!(
178	            "--task must be a slug of letters, digits, dot, dash and underscore (got '{task}')."
179	        ));
180	    }
181	    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
182	    let repo_root = providers::resolve_repo_root(&cwd);
183	    let given = Path::new(o.collab_dir.trim());
184	    let collab_root = if given.is_absolute() {
185	        given.to_path_buf()
186	    } else {
187	        repo_root.join(given)
188	    };
189	    let task_dir = collab_root.join(task);
190	    Ok((repo_root, collab_root, task_dir))
191	}
