193	/// The roster's worker entries: a worker engine (claude | codex | muse), role `worker` (the
194	/// EXISTING `roles` key — the design changes no schema).
195	fn worker_entries(roster: &Roster) -> Vec<&RosterEntry> {
196	    roster
197	        .entries
198	        .iter()
199	        .filter(|e| {
200	            // (ext.c3.inactive) an inactive entry is never a worker candidate.
201	            !e.inactive
202	                && WorkerEngine::parse(&e.engine).is_some()
203	                && e.roles.iter().any(|r| r == "worker")
204	        })
205	        .collect()
206	}
207	
208	fn worker_list(roster: &Roster) -> String {
209	    let workers = worker_entries(roster);
210	    if workers.is_empty() {
211	        "the roster has no worker entries (a worker engine — claude, codex or muse — with role \"worker\"); add \"roles\": [\"worker\"] to such an entry first.".to_string()
212	    } else {
213	        format!(
214	            "the roster's worker entries: {}",
215	            workers
216	                .iter()
217	                .map(|e| format!("{} :: {} [{}]", e.provider, e.model, e.engine))
218	                .collect::<Vec<_>>()
219	                .join(", ")
220	        )
221	    }
222	}
