224	/// The `--provider` lookup: a worker entry by label, with the design's refusals (a
225	/// non-worker label, a non-worker engine, an unknown label — each naming the workers).
226	fn select_worker(roster: &Roster, label: &str) -> Result<RosterEntry, String> {
227	    let workers = worker_entries(roster);
228	    if let Some(e) = workers.iter().find(|e| e.provider == label) {
229	        return Ok((*e).clone());
230	    }
231	    // (ext.c3.inactive) a direct request for an inactive worker label fails clearly.
232	    if roster
233	        .entries
234	        .iter()
235	        .any(|e| e.provider == label && e.inactive)
236	    {
237	        return Err(format!(
238	            "reviewer '{label}' is inactive (ext.c3.inactive in the roster)"
239	        ));
240	    }
241	    if let Some(e) = roster.entries.iter().find(|e| e.provider == label) {
242	        if WorkerEngine::parse(&e.engine).is_none() {
243	            return Err(format!(
244	                "the roster entry '{label}' runs on the '{}' engine; workers run on the engines {}. {}",
245	                e.engine,
246	                engines::WORKER_ENGINE_LIST,
247	                worker_list(roster)
248	            ));
249	        }
250	        return Err(format!(
251	            "the roster entry '{label}' is not a worker (its roles have no \"worker\"). {}",
252	            worker_list(roster)
253	        ));
254	    }
255	    Err(format!(
256	        "no roster entry '{label}'. {}",
257	        worker_list(roster)
258	    ))
259	}
