261	/// Every guard a run needs, in one place (the foreground and the detached background
262	/// both come through here; the live-run exclusion is NOT here — the run's own `running`
263	/// record is live by then, so [`run`] checks it before it allocates one).
264	fn prepare(o: &mut Options) -> Result<Prepared, String> {
265	    if !o.effort.trim().is_empty() && !EFFORTS.contains(&o.effort.trim()) {
266	        return Err(format!(
267	            "--effort must be one of {} (got '{}')",
268	            EFFORTS.join("|"),
269	            o.effort
270	        ));
271	    }
272	    if o.brief.trim().is_empty() {
273	        return Err("--brief is required (a file the worker works from).".into());
274	    }
275	    if o.provider.trim().is_empty() {
276	        return Err("--provider is required (a roster label with role \"worker\").".into());
277	    }
278	    let (repo_root, collab_root, task_dir) = prepare_paths(o)?;
279	    let work_root = task_dir.join("work");
280	
281	    // The brief: repo-relative or absolute, resolved to absolute so the detached
282	    // background (cwd = the repo root) reads the same file.
283	    let brief_path = Path::new(&o.brief);
284	    let brief_abs = if brief_path.is_absolute() {
285	        brief_path.to_path_buf()
286	    } else {
287	        repo_root.join(brief_path)
288	    };
289	    let brief_text = std::fs::read_to_string(&brief_abs).map_err(|e| {
290	        format!(
291	            "the brief '{}' could not be read ({e})",
292	            brief_abs.display()
293	        )
294	    })?;
295	    o.brief = brief_abs.to_string_lossy().to_string();
296	
297	    let collab_rel = c3_core::paths::repo_relative(&repo_root, &collab_root)
298	        .map(|r| format!("{}/", r.replace('\\', "/").trim_end_matches('/')))
299	        .unwrap_or_default();
300	
301	    // (0.2.5) A tests run: the role, the author's change, the scope.
302	    let role = o.role.trim().to_string();
303	    if !role.is_empty() && role != "tests" {
304	        return Err(format!("--role must be 'tests' (got '{role}')"));
305	    }
306	    if !o.of.trim().is_empty() && role != "tests" {
307	        return Err(
308	            "--of names the run whose change a tests run tests; it needs --role tests".into(),
309	        );
310	    }
311	    let mut scope: Vec<String> = Vec::new();
312	    for g in &o.scope {
313	        let g = g.trim().replace('\\', "/");
314	        globset::Glob::new(&g).map_err(|e| format!("--scope '{g}' is not a valid glob ({e})"))?;
315	        scope.push(g);
316	    }
317	    let mut tests_block = String::new();
318	    let mut of_id = String::new();
319	    if role == "tests" {
320	        scope.extend(TEST_SCOPE_DEFAULTS.iter().map(|s| s.to_string()));
321	        let (who, patch) = if o.of.trim().is_empty() {
322	            (
323	                "the working tree's change against HEAD".to_string(),
324	                record::worktree_patch(&repo_root, &collab_rel),
325	            )
326	        } else {
327	            let (dir, author) = pick_run(&work_root, o.of.trim(), &["done"])?;
328	            if author.status != "done" {
329	                return Err(format!(
330	                    "--of {}: the run is {}, not done; a tests run tests a finished change",
331	                    author.id, author.status
332	                ));
333	            }
334	            if author.provider == o.provider.trim() {
335	                eprintln!(
336	                    "{TOOL}: warning: the tests run uses the author's own provider '{}' (same family, same plan) - a different family catches more",
337	                    author.provider
338	                );
339	            }
340	            let patch = std::fs::read_to_string(dir.join("patch.diff")).map_err(|_| {
341	                format!(
342	                    "--of {}: the run has no patch.diff (recorded before 0.2.5); rerun it or test the working tree without --of",
343	                    author.id
344	                )
345	            })?;
346	            of_id = author.id.clone();
347	            (
348	                format!(
349	                    "work run {} ({} :: {})",
350	                    author.id, author.provider, author.model
351	                ),
352	                patch,
353	            )
354	        };
355	        if patch.trim().is_empty() {
356	            return Err(format!("nothing to test: {who} is empty"));
357	        }
358	        tests_block = format!(
359	            "{TESTS_PREAMBLE}\n\nThe change ({who}):\n<author-change>\n{}\n</author-change>",
360	            sanitize(patch.trim_end())
361	        );
362	    }
363	
364	    // The prompt: preamble [+ the tests block] + brief + --prompt, refused above the engine's
365	    // cap.
366	    let mut prompt = claude::WORK_PREAMBLE.to_string();
367	    if !tests_block.is_empty() {
368	        prompt.push_str("\n\n");
369	        prompt.push_str(&tests_block);
370	    }
371	    prompt.push_str("\n\n");
372	    prompt.push_str(&brief_text);
373	    if !o.prompt.trim().is_empty() {
374	        prompt.push_str("\n\n");
375	        prompt.push_str(&o.prompt);
376	    }
377	    if prompt.len() as u64 > MAX_PROMPT_BYTES {
378	        return Err(format!(
379	            "the prompt is {} bytes, above the engine's {}-byte cap; shorten the brief",
380	            prompt.len(),
381	            MAX_PROMPT_BYTES
382	        ));
383	    }
384	
385	    // The roster entry.
386	    let roster = providers::read_reviewer_roster()?;
387	    let entry = select_worker(&roster, o.provider.trim())?;
388	    let engine = WorkerEngine::parse(&entry.engine).ok_or_else(|| {
389	        format!(
390	            "the roster entry '{}' runs on the '{}' engine; workers run on the engines {}",
391	            o.provider.trim(),
392	            entry.engine,
393	            engines::WORKER_ENGINE_LIST
394	        )
395	    })?;
396	    let model = if o.model.trim().is_empty() {
397	        entry.model.clone()
398	    } else {
399	        o.model.trim().to_string()
400	    };
401	
402	    // (0.2.4, F89-4) Unrestricted execution is an explicit operator opt-in: the `--unrestricted`
403	    // flag, or the roster entry's `ext.unrestricted: true`.
404	    let unrestricted = o.unrestricted || entry.unrestricted;
405	
406	    // (0.2.4, F89-4) The muse worker disables its shell sandbox (`--disable-sandbox`): there is no
407	    // real containment, so it is refused unless the operator opted in.
408	    if engine == WorkerEngine::Muse && !unrestricted {
409	        return Err(
410	            "the muse worker runs with --disable-sandbox (no shell containment); pass --unrestricted (or set \"ext\": {\"unrestricted\": true} on its roster entry) to allow it"
411	                .into(),
412	        );
413	    }
414	
415	    // (0.2.5) A tests run reads the author's change: text planted in it would reach a worker with
416	    // an unrestricted shell. The muse worker has no other mode, so it never writes tests.
417	    if role == "tests" && engine == WorkerEngine::Muse {
418	        return Err(
419	            "a --role tests run reads another author's change; the muse worker runs an unrestricted shell, so text planted in that change could drive it - use a claude or codex worker".into(),
420	        );
421	    }
422	
423	    // The engine's credentials must be usable NOW: a guard of the design's "before anything
424	    // starts" list, so it is checked here too — `run_prepared` re-checks it, but by then a
425	    // record directory would already exist. claude: the endpoint's token variable; muse: the
426	    // per-token-billing / oauth launch guard; codex: none (a missing ChatGPT login fails the run).
427	    engine_launch_guard(engine, &entry)?;
428	
429	    // The allow list: the defaults when empty; a pattern naming git is refused — a
430	    // worker never commits (unless --unrestricted lifts the whole grammar).
431	    let allow = if o.allow.is_empty() {
432	        claude::WORK_DEFAULT_ALLOWS
433	            .iter()
434	            .map(|s| s.to_string())
435	            .collect()
436	    } else {
437	        o.allow.clone()
438	    };
439	    if !unrestricted {
440	        // The pattern is never echoed (it could carry a credential): the position is named.
441	        if let Some(i) = allow.iter().position(|p| p.to_lowercase().contains("git")) {
442	            return Err(format!(
443	                "--allow pattern #{} names git: a worker never runs git (the preamble forbids it; the allow list must not invite it)",
444	                i + 1
445	            ));
446	        }
447	        // (0.2.4, F89-4) A real allow-list grammar for operator-supplied patterns (the trusted
448	        // defaults are exempt): each must be <Tool>, <Tool>(<exe>) or <Tool>(<exe>:*) with <exe>
449	        // a plain executable name. The refusal names the POSITION only — never the pattern, which
450	        // could carry a credential.
451	        for (i, p) in o.allow.iter().enumerate() {
452	            if let Err(why) = validate_allow_pattern(p) {
453	                return Err(format!(
454	                    "--allow pattern #{} is not a valid restricted tool pattern: {why}; pass --unrestricted to lift the allow-list grammar",
455	                    i + 1
456	                ));
457	            }
458	        }
459	    }
460	
461	    // (0.2.4, F89-4) The effective permission boundary, recorded in run.json.
462	    let permission = match engine {
463	        WorkerEngine::Claude if unrestricted => {
464	            "claude, unrestricted (allow-list grammar lifted)".to_string()
465	        }
466	        WorkerEngine::Claude => "claude --allowedTools allow list".to_string(),
467	        WorkerEngine::Codex => {
468	            "codex --sandbox workspace-write (the allow list does not apply to codex)".to_string()
469	        }
470	        WorkerEngine::Muse => {
471	            "muse --disable-sandbox, unrestricted (the allow list does not apply to muse)"
472	                .to_string()
473	        }
474	    };
475	
476	    // The defaults a wire must carry explicitly.
477	    if o.max_turns <= 0 {
478	        o.max_turns = claude::WORK_MAX_TURNS_DEFAULT as i64;
479	    }
480	    if o.timeout_sec <= 0 {
481	        o.timeout_sec = 3600;
482	    }
483	
484	    // The launcher (the review engine's own resolution: the PATH names, then the
485	    // install locations).
486	    let launcher = resolve_worker_launcher(engine)?;
487	
488	    Ok(Prepared {
489	        repo_root,
490	        collab_root,
491	        task_dir,
492	        work_root,
493	        provider: entry.provider.clone(),
494	        model,
495	        engine,
496	        entry,
497	        allow,
498	        launcher,
499	        prompt,
500	        unrestricted,
501	        permission,
502	        role,
503	        of: of_id,
504	        scope,
505	    })
506	}
