508	/// (0.2.4, F89-4) Validate one operator `--allow` pattern against the restricted grammar:
509	/// `<Tool>`, `<Tool>(<exe>)` or `<Tool>(<exe>:*)` where `<exe>` is a plain executable name
510	/// (`[A-Za-z0-9_.+-]+`, optionally followed by plain subcommand words such as `cargo test` — no
511	/// wildcards, quotes or shell operators) and is not a shell or git. Returns
512	/// why it is invalid (never echoing the pattern, which could carry a credential; the forbidden
513	/// shell/git keyword is safe to name).
514	fn validate_allow_pattern(p: &str) -> Result<(), String> {
515	    // (0.2.4, F89-4 remainder) The tools that may appear BARE (no executable): read/write tools
516	    // that run no shell. A bare shell/exec tool (e.g. `Bash`) is refused — it must name an exe.
517	    const BARE_OK: &[&str] = &[
518	        "Read",
519	        "Edit",
520	        "Write",
521	        "Glob",
522	        "Grep",
523	        "MultiEdit",
524	        "NotebookEdit",
525	        "WebFetch",
526	        "WebSearch",
527	    ];
528	    // Shells AND interpreters AND git: compared against the exe BASENAME, lowercased, with a
529	    // trailing .exe/.cmd/.bat/.ps1 stripped.
530	    const DENY: &[&str] = &[
531	        "sh",
532	        "bash",
533	        "zsh",
534	        "fish",
535	        "dash",
536	        "pwsh",
537	        "powershell",
538	        "cmd",
539	        "wsl",
540	        "python",
541	        "python3",
542	        "py",
543	        "node",
544	        "deno",
545	        "bun",
546	        "perl",
547	        "ruby",
548	        "php",
549	        "git",
550	    ];
551	    // `<exe>` is a plain executable name, optionally followed by plain subcommand words
552	    // (`cargo test`, `npm run lint`): single spaces only, a word never starts with `-` (flags such
553	    // as `python -c` / `node -e` are where shell escapes hide), no wildcards, no shell operators,
554	    // and — because the class excludes `/` and `\` — no path separators.
555	    let re = regex::Regex::new(
556	        r"^([A-Za-z][A-Za-z0-9_]*)(?:\(([A-Za-z0-9_.+-]+)((?: [A-Za-z0-9][A-Za-z0-9_.+-]*)*)(?::\*)?\))?$",
557	    )
558	    .expect("valid regex");
559	    let caps = re.captures(p.trim()).ok_or_else(|| {
560	        "expected <Tool>, <Tool>(<exe>) or <Tool>(<exe>:*) with <exe> a plain executable name (letters, digits, '.', '_', '+', '-') optionally followed by plain subcommand words (never flags); no wildcards, quotes, shell operators or path separators".to_string()
561	    })?;
562	    let tool = caps.get(1).map(|m| m.as_str()).unwrap_or("");
563	    match caps.get(2) {
564	        None => {
565	            // A bare tool is allowed only for the non-shell whitelist.
566	            if !BARE_OK.contains(&tool) {
567	                return Err(format!(
568	                    "a bare '{tool}' is not allowed in restricted mode; name an executable, e.g. {tool}(cargo:*)"
569	                ));
570	            }
571	        }
572	        Some(exe) => {
573	            let lower = exe.as_str().to_lowercase();
574	            let base = [".exe", ".cmd", ".bat", ".ps1"]
575	                .iter()
576	                .find_map(|s| lower.strip_suffix(s))
577	                .unwrap_or(lower.as_str());
578	            if DENY.contains(&base) {
579	                return Err(format!(
580	                    "the '{}' executable is a shell, interpreter or git, which a worker may not be granted",
581	                    exe.as_str()
582	                ));
583	            }
584	        }
585	    }
586	    Ok(())
587	}
