589	/// The "before anything starts" credential guard of a worker engine: claude re-uses the review
590	/// engine's endpoint environment (its `problem` is the unset-token refusal); muse re-uses the
591	/// per-token-billing / oauth launch guard; codex has none.
592	fn engine_launch_guard(engine: WorkerEngine, entry: &RosterEntry) -> Result<(), String> {
593	    match engine {
594	        WorkerEngine::Claude => {
595	            let env = claude_auth::child_env(&entry.auth, entry.endpoint.as_ref());
596	            if env.problem.is_empty() {
597	                Ok(())
598	            } else {
599	                Err(format!(
600	                    "the entry's endpoint is not usable: {}",
601	                    env.problem
602	                ))
603	            }
604	        }
