668	/// Run the work child against an existing `running` record (the foreground after it
669	/// allocated the record; the detached background after it took the wire). Re-derives
670	/// [`Prepared`] — every guard runs again — then writes `brief.md`, runs the child with
671	/// the endpoint's child environment, and makes the record final.
672	pub fn run_prepared(o: &Options, rec_dir: &Path, _id: &str, _seq: i64, detached: bool) -> i32 {
673	    let mut o = o.clone();
674	    let pre = match prepare(&mut o) {
675	        Ok(p) => p,
676	        Err(why) => return refuse_record(rec_dir, &why),
677	    };
678	
679	    // brief.md: the prompt as sent (muse also reads it as its `--prompt-file`).
680	    let brief_md = rec_dir.join("brief.md");
681	    if let Err(e) = std::fs::write(&brief_md, &pre.prompt) {
682	        return refuse_record(rec_dir, &format!("could not write brief.md ({e})"));
683	    }
684	
685	    // The child environment: claude travels the endpoint route (token read at launch, host
686	    // markers scrubbed); codex/muse inherit the parent environment (`env: None`).
687	    let (child_env, scrubbed) = match worker_child_env(pre.engine, &pre.entry) {
688	        Ok(x) => x,
689	        Err(why) => return refuse_record(rec_dir, &why),
690	    };
691	
692	    // The argv (no secrets travel in it) and the record's launch fields. claude/muse mint the
693	    // session id up front, so a quota resume continues THIS session; codex names its thread in
694	    // the stream, read back after the run.
695	    let repo_root_s = pre.repo_root.to_string_lossy().to_string();
696	    let effort = (!o.effort.trim().is_empty()).then(|| o.effort.trim().to_string());
697	    let mut session_id = match pre.engine {
698	        WorkerEngine::Claude | WorkerEngine::Muse => uuid::Uuid::new_v4().to_string(),
699	        WorkerEngine::Codex => String::new(),
700	    };
701	    let argv = match pre.engine {
702	        WorkerEngine::Claude => claude::work_args(&ClaudeWorkArgs {
703	            model: pre.model.clone(),
704	            effort: effort.clone(),
705	            max_turns: o.max_turns.clamp(1, u32::MAX as i64) as u32,
706	            allowed_tools: pre.allow.clone(),
707	            session_id: session_id.clone(),
708	            resume: false,
709	        }),
710	        WorkerEngine::Codex => {
711	            engines::codex_work_args(&pre.model, effort.as_deref(), &repo_root_s, None)
712	        }
713	        WorkerEngine::Muse => engines::muse_work_args(
714	            &pre.model,
715	            effort.as_deref(),
716	            &repo_root_s,
717	            &brief_md.to_string_lossy(),
718	            &session_id,
719	        ),
720	    };
721	    let before = status_short(&pre.repo_root);
722	    let before_hashes = record::baseline_hashes(&pre.repo_root, &before);
723	    if let Ok(Some(mut rec)) = read_record(rec_dir) {
724	        // (0.2.4, F89-5) the persisted argv passes the sanitizer (flags/uuids/grammar-safe allow
725	        // values are untouched; a secret-shaped value would be redacted).
726	        rec.argv = sanitize_argv(&argv);
727	        rec.child_env_scrubbed = scrubbed;
728	        rec.timeout_sec = o.timeout_sec;
729	        rec.session_id = session_id.clone();
730	        rec.baseline = before.clone();
731	        rec.baseline_hashes = before_hashes.clone();
732	        rec.role = pre.role.clone();
733	        rec.of = pre.of.clone();
734	        rec.scope = pre.scope.clone();
735	        if let Err(e) = write_record(rec_dir, &rec) {
736	            return refuse(&format!(
737	                "the work run could not report to {} ({e}); nothing was started.",
738	                rec_dir.join("run.json").display()
739	            ));
740	        }
741	    }
742	
743	    println!(
744	        "{TOOL}: work run starting ({} :: {} [{}]) in {}",
745	        pre.provider,
746	        pre.model,
747	        pre.engine.as_str(),
748	        pre.repo_root.display()
749	    );
750	    let events_path = rec_dir.join("events.jsonl");
751	    let stderr_path = rec_dir.join(".stderr");
752	    // muse takes its prompt through the `--prompt-file` in the argv (stdin empty); claude/codex
753	    // take it on stdin.
754	    let stdin_text = match pre.engine {
755	        WorkerEngine::Muse => "",
756	        _ => pre.prompt.as_str(),
757	    };
758	    let spawn = SpawnRequest {
759	        launcher: &pre.launcher,
760	        argv: &argv,
761	        cwd: &pre.repo_root,
762	        prompt_delivery: pre.engine.prompt_delivery(),
763	        stdin_text,
764	        events_path: &events_path,
765	        stderr_path: &stderr_path,
766	        timeout: Duration::from_secs(o.timeout_sec.max(1) as u64),
767	        stall_sec: 0,
768	        kick_path: None,
769	        tool_flight: None,
770	        on_running: None,
771	        on_kill: None,
772	        env: child_env.as_deref(),
773	        crt_quote: matches!(pre.engine, WorkerEngine::Claude),
774	        budget: None,
775	    };
776	    let result = run_turn(&spawn);
777	
778	    // codex names its thread only in the stream: read it back so a resume can continue it.
779	    let events_text = std::fs::read_to_string(&events_path).unwrap_or_default();
780	    if session_id.trim().is_empty() {
781	        let parsed = engines::session_from_events(pre.engine, &events_text);
782	        if !parsed.is_empty() {
783	            session_id = parsed;
784	        }
785	    }
786	
787	    // Classify THIS attempt from its own stream/stderr, then refresh the record artifacts over
788	    // the whole stream and make the record final (quota included).
789	    let (status, quota_text, reset_at, reason) = classify_attempt(
790	        pre.engine,
791	        &events_text,
792	        &std::fs::read_to_string(&stderr_path).unwrap_or_default(),
793	        result.stop == crate::engines::subprocess::TurnStop::Timeout,
794	        result.exit_code,
795	    );
796	    let window = eff_window(&o, pre.entry.quota_window_sec);
797	    // (0.2.4, F89-3) An artifact write failure makes the run `artifact_error`, never `done`.
798	    let mut rec =
799	        match refresh_artifacts(pre.engine, rec_dir, &pre.repo_root, &before, &before_hashes) {
800	            Ok(r) => r,
801	            Err(e) => return finish_artifact_error(rec_dir, result.exit_code, &e),
802	        };
803	    rec.session_id = session_id.clone();
804	    rec.exit_code = result.exit_code.map(|c| c as i64);
805	    rec.timeout_sec = o.timeout_sec;
806	    rec.status = status.clone();
807	    rec.ended = Some(iso_now());
808	    rec.error = if status == "died" {
809	        reason
810	    } else {
811	        String::new()
812	    };
813	    if status == "quota" {
814	        rec.quota = Some(build_quota(&quota_text, reset_at, window, 0, false));
815	    }
816	    if let Err(e) = write_record(rec_dir, &rec) {
817	        return refuse(&format!(
818	            "the work run could not write its final record ({e})."
819	        ));
820	    }
821	    if !result.started {
822	        return refuse(&format!(
823	            "the claude process did not start ({})",
824	            result.error.unwrap_or_else(|| "no reason given".into())
825	        ));
826	    }
827	    print_run_line(&rec);
828	
829	    // A quota hit: a detached run sleeps and resumes itself (the alarm); a foreground run prints
830	    // how to resume and exits 3.
831	    if rec.status == "quota" {
832	        if detached {
833	            return run_alarm(&o, rec_dir);
834	        }
835	        return foreground_quota(&o, rec_dir, &rec);
836	    }
837	    scope_exit(&rec, exit_for(&rec.status))
838	}
