941	/// (0.2.4, F89-2) Claim a DETACHED run's placeholder record for its first spawn under the task
942	/// admission lock: refuse if any other run is live or the inspection fails; the record must still
943	/// be the `running` placeholder this process owns. Writes pid + start + attempt 0 durably before
944	/// the caller spawns.
945	fn claim_start(work_root: &Path, rec_dir: &Path) -> Result<RunRecord, String> {
946	    let _lock = record::admission_lock(work_root)?;
947	    if let Some(other) = record::other_live_run(work_root, rec_dir)? {
948	        return Err(format!("task already has a live work run ({other})"));
949	    }
950	    let mut rec = read_record(rec_dir)?
951	        .ok_or_else(|| "the work record vanished before it could be claimed".to_string())?;
952	    if rec.status != "running" {
953	        return Err(format!(
954	            "work run {} is in state {}, not the fresh placeholder; refusing to launch",
955	            rec.id, rec.status
956	        ));
957	    }
958	    let (pid, start) = record::self_owner();
959	    if record::is_live(&rec) && rec.pid.is_some() && rec.pid != Some(pid) {
960	        return Err(format!(
961	            "work run {} is already live under pid {}; refusing a second launch",
962	            rec.id,
963	            rec.pid.unwrap_or(0)
964	        ));
965	    }
966	    rec.pid = Some(pid);
967	    rec.pid_start = start;
968	    rec.attempt = 0;
969	    rec.ended = None;
970	    rec.error = String::new();
971	    rec.args = None;
972	    write_record(rec_dir, &rec)?;
973	    Ok(rec)
974	}
