976	/// (0.2.4, F91-1) Claim a run for a RESUME spawn under the task admission lock, validating
977	/// EVERYTHING against the locked re-read, not the caller's earlier unlocked read: no other run is
978	/// live, this record is still in a resumable state (`quota`/`timeout`), it is NOT exhausted, it is
979	/// not already live under another owner, and the attempt generation the caller expected still
980	/// holds. The next attempt number is computed from THIS locked record, so a stale claim (now
981	/// `done`/`exhausted`/already advanced by a concurrent resume) refuses before any spawn. Returns
982	/// the claimed record and the attempt number `n`.
983	fn claim_resume(
984	    work_root: &Path,
985	    rec_dir: &Path,
986	    expected_resumes: i64,
987	) -> Result<(RunRecord, i64), String> {
988	    let _lock = record::admission_lock(work_root)?;
989	    if let Some(other) = record::other_live_run(work_root, rec_dir)? {
990	        return Err(format!("task already has a live work run ({other})"));
991	    }
992	    let mut rec = read_record(rec_dir)?
993	        .ok_or_else(|| "the work record vanished before it could be claimed".to_string())?;
994	    // Resumable states: `quota`/`timeout` for a foreground --resume, and `waiting_quota` for the
995	    // detached alarm (which parked the record before it resumes in-process). A terminal state
996	    // (done/died/exhausted) means a concurrent resume/completion won: refuse the stale claim.
997	    if !matches!(rec.status.as_str(), "quota" | "timeout" | "waiting_quota") {
998	        return Err(format!(
999	            "work run {} is in state {}, not resumable; nothing to resume (it may have been completed or resumed concurrently)",
1000	            rec.id, rec.status
1001	        ));
1002	    }
1003	    if rec.quota.as_ref().map(|q| q.exhausted).unwrap_or(false) {
1004	        return Err(format!(
1005	            "work run {} has spent its resume cap; it needs a human",
1006	            rec.id
1007	        ));
1008	    }
1009	    let resumes = rec.quota.as_ref().map(|q| q.resumes).unwrap_or(0);
1010	    if resumes != expected_resumes {
1011	        return Err(format!(
1012	            "work run {} changed since it was read (resume {} now, {} expected); refusing a stale claim",
1013	            rec.id, resumes, expected_resumes
1014	        ));
1015	    }
1016	    let (pid, start) = record::self_owner();
1017	    if record::is_pending(&rec.status) && record::is_live(&rec) && rec.pid != Some(pid) {
1018	        return Err(format!(
1019	            "work run {} is already live under pid {}; refusing a second launch",
1020	            rec.id,
1021	            rec.pid.unwrap_or(0)
1022	        ));
1023	    }
1024	    let n = resumes + 1;
1025	    rec.status = "running".into();
1026	    rec.pid = Some(pid);
1027	    rec.pid_start = start;
1028	    rec.attempt = n;
1029	    rec.ended = None;
1030	    rec.error = String::new();
1031	    rec.args = None;
1032	    write_record(rec_dir, &rec)?;
1033	    Ok((rec, n))
1034	}
