1051	/// Classify one work attempt from ITS OWN stream and stderr (never a prior attempt's): the base
1052	/// status (`timeout` | `done` | `died`), turned into `quota` when the attempt did not succeed and
1053	/// the engine found a usage limit. Returns `(status, quota_text, reset_at)`.
1054	fn classify_attempt(
1055	    engine: WorkerEngine,
1056	    events_text: &str,
1057	    stderr_text: &str,
1058	    timed_out: bool,
1059	    exit_code: Option<i32>,
1060	) -> (String, String, Option<DateTime<Utc>>, String) {
1061	    let (quota_text, reset_at) = engines::quota_evidence(engine, events_text, stderr_text);
1062	    let outcome = engines::terminal_outcome(engine, events_text);
1063	    // (0.2.4, F89-8) A rejecting rate-limit / quota wording takes precedence over exit 0 (so a run
1064	    // resumes), UNLESS the engine also emitted a clean successful terminal. Otherwise success
1065	    // requires BOTH exit 0 AND the engine's successful terminal event; an error terminal or an
1066	    // empty stream fails closed (`died`), never `done`.
1067	    if !quota_text.is_empty() && outcome != engines::Terminal::Success {
1068	        return ("quota".to_string(), quota_text, reset_at, String::new());
1069	    }
1070	    if timed_out {
1071	        return ("timeout".to_string(), quota_text, reset_at, String::new());
1072	    }
1073	    let (status, reason) = match outcome {
1074	        engines::Terminal::Success if exit_code == Some(0) => ("done", String::new()),
1075	        engines::Terminal::Success => (
1076	            "died",
1077	            format!(
1078	                "the engine reported success but the process exited {}",
1079	                exit_code
1080	                    .map(|c| c.to_string())
1081	                    .unwrap_or_else(|| "(none)".into())
1082	            ),
1083	        ),
1084	        engines::Terminal::Error => ("died", "the engine reported an error result".to_string()),
1085	        engines::Terminal::None => ("died", "no terminal event".to_string()),
1086	    };
1087	    (status.to_string(), quota_text, reset_at, reason)
1088	}
