1090	/// A fresh [`Quota`] block: `resume_at` = `reset_at` + 60 s when the provider gave a reset time,
1091	/// else now + the quota window.
1092	fn build_quota(
1093	    quota_text: &str,
1094	    reset_at: Option<DateTime<Utc>>,
1095	    window_sec: i64,
1096	    resumes: i64,
1097	    exhausted: bool,
1098	) -> Quota {
1099	    let resume_at = match reset_at {
1100	        Some(r) => r + chrono::Duration::seconds(60),
1101	        None => Utc::now() + chrono::Duration::seconds(window_sec.max(60)),
1102	    };
1103	    Quota {
1104	        text: quota_text.to_string(),
1105	        reset_at: reset_at.map(|r| r.to_rfc3339()),
1106	        resume_at: resume_at.to_rfc3339(),
1107	        resumes,
1108	        exhausted,
1109	    }
1110	}
