1112	/// Recompute `report.md`, `diff.txt` and the summary fields over the WHOLE event stream (every
1113	/// attempt - the `{"type":"c3","subtype":"resume"}` separators are skipped by the summary) and the
1114	/// current git state against `before` (the first launch's baseline). Returns the record with its
1115	/// summary fields filled; the caller sets `status`, `ended`, `exit_code` and `quota`.
1116	fn refresh_artifacts(
1117	    engine: WorkerEngine,
1118	    rec_dir: &Path,
1119	    repo_root: &Path,
1120	    before: &[String],
1121	    before_hashes: &std::collections::BTreeMap<String, String>,
1122	) -> Result<RunRecord, String> {
1123	    // (0.2.4, F91-3) Read the aggregate stream STRICTLY: a transient read failure must NOT become
1124	    // an empty report. report.md is never replaced when its source cannot be read.
1125	    let events_text = read_events_strict(&rec_dir.join("events.jsonl"))?;
1126	    let sum = engines::summarize(engine, &events_text);
1127	    // (0.2.4, F89-3/F89-5) report.md and diff.txt write failures are propagated (the caller makes
1128	    // the run `artifact_error`), and both pass the project's single sanitizer so no secret-shaped
1129	    // value survives in them.
1130	    std::fs::write(rec_dir.join("report.md"), sanitize(&sum.report))
1131	        .map_err(|e| format!("could not write report.md ({e})"))?;
1132	    let after = status_short(repo_root);
1133	    let stat = diff_stat(repo_root);
1134	    std::fs::write(
1135	        rec_dir.join("diff.txt"),
1136	        sanitize(&diff_text(before, &after, &stat)),
1137	    )
1138	    .map_err(|e| format!("could not write diff.txt ({e})"))?;
1139	    let mut rec = read_record(rec_dir).ok().flatten().unwrap_or_default();
1140	    rec.turns = sum.turns;
1141	    rec.tool_calls = sum.tool_calls;
1142	    rec.files_changed = files_changed(before_hashes, &after, repo_root);
1143	    rec.usage = sum.usage;
1144	    // (0.2.5) patch.diff: what the run changed, from the baseline content (the record dir - under
1145	    // the collab directory - left out); the scope check over the same files.
1146	    let collab_rel = rec_dir
1147	        .ancestors()
1148	        .nth(3)
1149	        .and_then(|c| c3_core::paths::repo_relative(repo_root, c))
1150	        .map(|r| format!("{}/", r.replace('\\', "/").trim_end_matches('/')))
1151	        .unwrap_or_default();
1152	    let changed: Vec<String> = rec
1153	        .files_changed
1154	        .iter()
1155	        .filter(|p| collab_rel.is_empty() || !p.starts_with(&collab_rel))
1156	        .cloned()
1157	        .collect();
1158	    std::fs::write(
1159	        rec_dir.join("patch.diff"),
1160	        sanitize(&record::run_patch(repo_root, before_hashes, &changed)),
1161	    )
1162	    .map_err(|e| format!("could not write patch.diff ({e})"))?;
1163	    rec.scope_violations = record::scope_violations(repo_root, &rec.scope, &changed, &collab_rel);
1164	    Ok(rec)
1165	}
