1167	/// (0.2.4, F91-3) Read an event file STRICTLY: a genuinely absent file (`NotFound`) is an empty
1168	/// stream, but any other read error (permission, a path replaced by a directory) is propagated so
1169	/// the caller treats it as an artifact error rather than empty input.
1170	fn read_events_strict(path: &Path) -> Result<String, String> {
1171	    match std::fs::read(path) {
1172	        Ok(b) => Ok(String::from_utf8_lossy(&b).into_owned()),
1173	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(String::new()),
1174	        Err(e) => Err(format!("could not read {} ({e})", path.display())),
1175	    }
1176	}
