1178	/// (0.2.4, F89-5) The project's single outbound sanitizer: `run.json`, `report.md` and `diff.txt`
1179	/// pass through it (secret-shaped values redacted, the same rules as a pack). `events.jsonl` does
1180	/// NOT — it is the child's raw stream, retained verbatim.
1181	fn sanitize(text: &str) -> String {
1182	    crate::pack::redact::redact(text).0
1183	}
