1185	/// (0.2.4, F91-1) TEST-ONLY claim barrier (honoured only in test mode via `test_hooks::hook`):
1186	/// when `CODEX_CONSULT_TEST_WORK_CLAIM_BARRIER` names a path, wait (bounded) until it exists, so a
1187	/// test can interpose a competing resume between an unlocked read and the locked claim.
1188	fn test_claim_barrier() {
1189	    if let Some(gate) = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_WORK_CLAIM_BARRIER") {
1190	        let gate = PathBuf::from(gate);
1191	        for _ in 0..600 {
1192	            if gate.exists() {
1193	                return;
1194	            }
1195	            std::thread::sleep(Duration::from_millis(100));
1196	        }
1197	    }
1198	}
