1206	/// The entry point: `--status`/`--wait` read the records only; `--detach-id` is the
1207	/// background; anything else is a run (foreground, or detached once its record exists).
1208	pub fn run(mut o: Options) -> i32 {
1209	    if o.status || o.wait {
1210	        return detach::query(&o);
1211	    }
1212	    if !o.detach_id.trim().is_empty() {
1213	        return detach::background(&o);
1214	    }
1215	    if o.task.trim().is_empty() {
1216	        return refuse("--task is required (see c3 work --help).");
1217	    }
1218	    if o.resume || o.kick {
1219	        return resume_or_kick(&o);
1220	    }
1221	    let pre = match prepare(&mut o) {
1222	        Ok(p) => p,
1223	        Err(why) => return refuse(&why),
1224	    };
1225	    // (0.2.4, F89-1/F89-2) One task-level admission for starts: hold the admission lock across the
1226	    // live-run check, the allocation and the initial claim, so two starts cannot both pass. A
1227	    // foreground run writes its OWN pid + start time BEFORE the child is spawned (the owner that
1228	    // keeps the record `running` past the start grace); a detached run leaves the pid to its
1229	    // background (claimed within its first second).
1230	    let lock = match record::admission_lock(&pre.work_root) {
1231	        Ok(l) => l,
1232	        Err(e) => return refuse(&e),
1233	    };
1234	    match record::live_run(&pre.work_root) {
1235	        Ok(Some(id)) => {
1236	            return refuse(&format!(
1237	                "task '{}' already has a live work run ({id}); c3 work --task {}{} --wait waits for it",
1238	                o.task,
1239	                o.task,
1240	                if o.collab_dir != ".collab" {
1241	                    format!(" --collab-dir \"{}\"", o.collab_dir)
1242	                } else {
1243	                    String::new()
1244	                }
1245	            ));
1246	        }
1247	        Ok(None) => {}
1248	        // (0.2.4, F91-2) fail closed: a record that cannot be inspected refuses admission.
1249	        Err(e) => return refuse(&format!("cannot admit a work run: {e}")),
1250	    }
1251	    let (id, seq, rec_dir) = match record::allocate(&pre.work_root, &pre.provider, &pre.model) {
1252	        Ok(x) => x,
1253	        Err(e) => return refuse(&e),
1254	    };
1255	    let (pid, pid_start) = if o.detach {
1256	        (None, String::new())
1257	    } else {
1258	        let (p, s) = record::self_owner();
1259	        (Some(p), s)
1260	    };
1261	    let rec = RunRecord {
1262	        id: id.clone(),
1263	        task: o.task.clone(),
1264	        seq,
1265	        provider: pre.provider.clone(),
1266	        model: pre.model.clone(),
1267	        engine: pre.engine.as_str().into(),
1268	        child_env_scrubbed: Vec::new(),
1269	        started: iso_now(),
1270	        status: "running".into(),
1271	        timeout_sec: o.timeout_sec,
1272	        pid,
1273	        pid_start,
1274	        max_resumes: eff_max_resumes(&o),
1275	        quota_window_sec: eff_window(&o, pre.entry.quota_window_sec),
1276	        unrestricted: pre.unrestricted,
1277	        permission: pre.permission.clone(),
1278	        args: o.detach.then(|| detach::wire_of(&o, &pre.collab_root)),
1279	        ..Default::default()
1280	    };
1281	    if let Err(e) = write_record(&rec_dir, &rec) {
1282	        return refuse(&format!(
1283	            "the work run could not write {} ({e}); nothing was started.",
1284	            rec_dir.join("run.json").display()
1285	        ));
1286	    }
1287	    drop(lock);
1288	    if o.detach {
1289	        return detach::start_detached(&o, &pre, &id, &rec_dir);
1290	    }
1291	    run_prepared(&o, &rec_dir, &id, seq, false)
1292	}
