1296	/// The alarm's decision for one sleep slice: sleep a bounded slice, resume now, or give up because
1297	/// the resume cap is spent. A PURE function of the clock, the reset time, the kick file and the
1298	/// resume count - unit-tested without any real sleeping.
1299	#[derive(Debug, PartialEq, Eq)]
1300	pub(crate) enum AlarmAction {
1301	    Sleep(Duration),
1302	    Resume,
1303	    GiveUp,
1304	}
1305	
1306	/// [`AlarmAction`] for `now`: give up when `resumes >= max`; resume when the kick file exists or
1307	/// the window has reset; else sleep up to [`ALARM_SLICE_SEC`] (never past `resume_at`, never 0).
1308	pub(crate) fn next_action(
1309	    now: DateTime<Utc>,
1310	    resume_at: DateTime<Utc>,
1311	    kick_exists: bool,
1312	    resumes: i64,
1313	    max: i64,
1314	) -> AlarmAction {
1315	    if resumes >= max {
1316	        return AlarmAction::GiveUp;
1317	    }
1318	    if kick_exists || now >= resume_at {
1319	        return AlarmAction::Resume;
1320	    }
1321	    let secs = (resume_at - now).num_seconds().clamp(1, ALARM_SLICE_SEC);
1322	    AlarmAction::Sleep(Duration::from_secs(secs as u64))
1323	}
