1429	/// Append the resume separator line and this attempt's stream to `events.jsonl` (verbatim, the
1430	/// whole record kept in order).
1431	fn append_resume(rec_dir: &Path, n: i64, attempt_events: &str) -> Result<(), String> {
1432	    use std::io::Write;
1433	    let path = rec_dir.join("events.jsonl");
1434	    let needs_nl = std::fs::read(&path)
1435	        .ok()
1436	        .map(|b| !b.is_empty() && b.last() != Some(&b'\n'))
1437	        .unwrap_or(false);
1438	    // (0.2.4, F89-3) Every open/write/flush error is propagated — the caller keeps the attempt
1439	    // files and makes the run `artifact_error` rather than deleting them and reporting `done`.
1440	    let mut f = std::fs::OpenOptions::new()
1441	        .create(true)
1442	        .append(true)
1443	        .open(&path)
1444	        .map_err(|e| format!("could not open events.jsonl to append the resume ({e})"))?;
1445	    let mut write = |bytes: &[u8]| -> Result<(), String> {
1446	        f.write_all(bytes)
1447	            .map_err(|e| format!("could not append to events.jsonl ({e})"))
1448	    };
1449	    if needs_nl {
1450	        write(b"\n")?;
1451	    }
1452	    let sep = format!(
1453	        "{{\"type\":\"c3\",\"subtype\":\"resume\",\"n\":{n},\"at\":\"{}\"}}\n",
1454	        Utc::now().to_rfc3339()
1455	    );
1456	    write(sep.as_bytes())?;
1457	    let trimmed = attempt_events.trim_end_matches(['\n', '\r']);
1458	    if !trimmed.is_empty() {
1459	        write(trimmed.as_bytes())?;
1460	        write(b"\n")?;
1461	    }
1462	    f.flush()
1463	        .map_err(|e| format!("could not flush events.jsonl ({e})"))?;
1464	    f.sync_all()
1465	        .map_err(|e| format!("could not sync events.jsonl ({e})"))?;
1466	    Ok(())
1467	}
