1469	/// Resume the child once: relaunch with `--resume`, append the attempt to `events.jsonl`,
1470	/// recompute every artifact over the whole record, bump `quota.resumes`, and make the record final
1471	/// again (quota, exhausted, done, died or timeout). Returns the new status.
1472	fn resume_once(renv: &ResumeEnv, rec_dir: &Path) -> Result<String, String> {
1473	    let pre = read_record(rec_dir)?.ok_or_else(|| "the work record vanished".to_string())?;
1474	    let expected_resumes = pre.quota.as_ref().map(|q| q.resumes).unwrap_or(0);
1475	    // (0.2.4, F91-1) TEST-ONLY barrier (honoured only in test mode): pause here, AFTER the caller's
1476	    // unlocked read and BEFORE the locked claim, until the gate file appears — the acceptance test
1477	    // lets a competing resume finish/exhaust in this window, so the locked re-read below sees the
1478	    // stale state and refuses.
1479	    test_claim_barrier();
1480	    // (0.2.4, F89-2/F91-1) Claim under the task admission lock, validating the permitted state,
1481	    // exhaustion, owner and attempt generation against the LOCKED re-read; the attempt number `n`
1482	    // comes from that record, so a stale claim refuses before spawning.
1483	    let work_root = rec_dir.parent().unwrap_or(rec_dir).to_path_buf();
1484	    let (rec, n) = claim_resume(&work_root, rec_dir, expected_resumes)?;
1485	    println!(
1486	        "{TOOL}: resuming work run {} ({} :: {}) - resume {}/{}",
1487	        rec.id, rec.provider, rec.model, n, renv.max_resumes
1488	    );
1489	    // (0.2.4, F89-2) Per-attempt file names (never a fixed path two resumes could overwrite).
1490	    let tmp_events = rec_dir.join(format!(".events-resume-{n}.jsonl"));
1491	    let tmp_stderr = rec_dir.join(format!(".stderr-resume-{n}"));
1492	    let _ = std::fs::remove_file(&tmp_events);
1493	    let _ = std::fs::remove_file(&tmp_stderr);
1494	    let spawn = SpawnRequest {
1495	        launcher: &renv.launcher,
1496	        argv: &renv.argv,
1497	        cwd: &renv.repo_root,
1498	        prompt_delivery: renv.prompt_delivery,
1499	        stdin_text: &renv.stdin_text,
1500	        events_path: &tmp_events,
1501	        stderr_path: &tmp_stderr,
1502	        timeout: Duration::from_secs(renv.timeout_sec.max(1) as u64),
1503	        stall_sec: 0,
1504	        kick_path: None,
1505	        tool_flight: None,
1506	        on_running: None,
1507	        on_kill: None,
1508	        env: renv.env.as_deref(),
1509	        crt_quote: renv.crt_quote,
1510	        budget: None,
1511	    };
1512	    let result = run_turn(&spawn);
1513	    // (0.2.4, F91-3) Read the attempt stream STRICTLY: an unreadable attempt file is an artifact
1514	    // error, and the per-attempt temp files are PRESERVED (not deleted) so the bytes are
1515	    // recoverable — never append an empty attempt and then delete its source.
1516	    let attempt_events = match read_events_strict(&tmp_events) {
1517	        Ok(t) => t,
1518	        Err(e) => {
1519	            let _ = finish_artifact_error(rec_dir, result.exit_code, &e);
1520	            return Ok("artifact_error".to_string());
1521	        }
1522	    };
1523	    let attempt_stderr = std::fs::read_to_string(&tmp_stderr).unwrap_or_default();
1524	
1525	    let (status, quota_text, reset_at, reason) = classify_attempt(
1526	        renv.engine,
1527	        &attempt_events,
1528	        &attempt_stderr,
1529	        result.stop == crate::engines::subprocess::TurnStop::Timeout,
1530	        result.exit_code,
1531	    );
1532	    // (0.2.4, F89-3) Append the attempt to events.jsonl durably FIRST; the per-attempt files are
1533	    // deleted only after the append succeeded and was flushed. A failed append keeps them and
1534	    // makes the run `artifact_error` (never `done`, never a deleted-then-lost report).
1535	    if let Err(e) = append_resume(rec_dir, n, &attempt_events) {
1536	        let _ = finish_artifact_error(rec_dir, result.exit_code, &e);
1537	        return Ok("artifact_error".to_string());
1538	    }
1539	    let _ = std::fs::remove_file(&tmp_events);
1540	    let _ = std::fs::remove_file(&tmp_stderr);
1541	
1542	    let before = rec.baseline.clone();
1543	    let before_hashes = rec.baseline_hashes.clone();
1544	    let mut nrec = match refresh_artifacts(
1545	        renv.engine,
1546	        rec_dir,
1547	        &renv.repo_root,
1548	        &before,
1549	        &before_hashes,
1550	    ) {
1551	        Ok(r) => r,
1552	        Err(e) => {
1553	            let _ = finish_artifact_error(rec_dir, result.exit_code, &e);
1554	            return Ok("artifact_error".to_string());
1555	        }
1556	    };
1557	    nrec.exit_code = result.exit_code.map(|c| c as i64);
1558	    nrec.ended = Some(iso_now());
1559	    nrec.status = status.clone();
1560	    nrec.error = if status == "died" {
1561	        reason
1562	    } else {
1563	        String::new()
1564	    };
1565	    if status == "quota" {
1566	        let exhausted = n >= renv.max_resumes;
1567	        nrec.quota = Some(build_quota(
1568	            &quota_text,
1569	            reset_at,
1570	            renv.window_sec,
1571	            n,
1572	            exhausted,
1573	        ));
1574	    } else if let Some(q) = nrec.quota.as_mut() {
1575	        // success/death after a quota: keep the last evidence, record how many resumes it took
1576	        q.resumes = n;
1577	    }
1578	    write_record(rec_dir, &nrec)?;
1579	    print_run_line(&nrec);
1580	    if !result.started {
1581	        return Err(format!(
1582	            "the claude process did not start ({})",
1583	            result.error.unwrap_or_else(|| "no reason given".into())
1584	        ));
1585	    }
1586	    Ok(status)
1587	}
