1589	/// A foreground run parked on quota: print the resume time and the exact resume command, exit 3;
1590	/// or, when the resume cap is spent, report it and exit 1.
1591	fn foreground_quota(o: &Options, rec_dir: &Path, rec: &RunRecord) -> i32 {
1592	    let q = rec.quota.clone().unwrap_or_default();
1593	    let collab_flag = if o.collab_dir != ".collab" && !o.collab_dir.is_empty() {
1594	        format!(" --collab-dir \"{}\"", o.collab_dir)
1595	    } else {
1596	        String::new()
1597	    };
1598	    if q.exhausted {
1599	        eprintln!(
1600	            "{TOOL}: work run {} hit its usage limit and spent the resume cap ({}): {}. It needs a human; the record is at {}.",
1601	            rec.id,
1602	            eff_max_resumes_rec(o, rec),
1603	            q.text,
1604	            rec_dir.display()
1605	        );
1606	        return 1;
1607	    }
1608	    println!("{TOOL}: work run {} hit a usage limit: {}", rec.id, q.text);
1609	    println!("resume at : {} ({})", local_time(&q.resume_at), q.resume_at);
1610	    println!(
1611	        "resume now: c3 work --task {}{} --resume {}",
1612	        o.task, collab_flag, rec.id
1613	    );
1614	    3
1615	}
1616	
1617	/// The detached alarm: the background does NOT exit on quota. It parks the run `waiting_quota`,
1618	/// sleeps in slices (waking on the kick file), resumes the child in-process when the window
1619	/// resets, and repeats on a further quota hit until the cap. Returns the final exit code.
1620	fn run_alarm(o: &Options, rec_dir: &Path) -> i32 {
1621	    let rec0 = match read_record(rec_dir) {
1622	        Ok(Some(r)) => r,
1623	        _ => return 1,
1624	    };
1625	    let renv = match resume_env(o, &rec0, rec_dir) {
1626	        Ok(e) => e,
1627	        Err(why) => {
1628	            eprintln!("{TOOL}: cannot arm the quota resume for {}: {why}", rec0.id);
1629	            return 1;
1630	        }
1631	    };
1632	    let kick = rec_dir.join(".kick");
1633	    loop {
1634	        let rec = match read_record(rec_dir) {
1635	            Ok(Some(r)) => r,
1636	            _ => return 1,
1637	        };
1638	        if !record::is_pending(&rec.status) && rec.status != "quota" {
1639	            return exit_for(&rec.status);
1640	        }
1641	        let q = match &rec.quota {
1642	            Some(q) => q.clone(),
1643	            None => return 1,
1644	        };
1645	        if q.exhausted {
1646	            return 1;
1647	        }
1648	        // park the run waiting_quota (the background stays alive; its pid is kept)
1649	        if rec.status != "waiting_quota" {
1650	            let mut wrec = rec.clone();
1651	            wrec.status = "waiting_quota".into();
1652	            let _ = write_record(rec_dir, &wrec);
1653	            println!(
1654	                "{TOOL}: work run {} is waiting for its usage limit to reset, until {} (resume {}/{})",
1655	                rec.id,
1656	                local_time(&q.resume_at),
1657	                q.resumes,
1658	                renv.max_resumes
1659	            );
1660	        }
1661	        let resume_at = parse_utc(&q.resume_at);
1662	        loop {
1663	            match next_action(
1664	                Utc::now(),
1665	                resume_at,
1666	                kick.exists(),
1667	                q.resumes,
1668	                renv.max_resumes,
1669	            ) {
1670	                AlarmAction::Sleep(d) => std::thread::sleep(d),
1671	                AlarmAction::Resume => {
1672	                    let _ = std::fs::remove_file(&kick);
1673	                    break;
1674	                }
1675	                AlarmAction::GiveUp => {
1676	                    let mut er = rec.clone();
1677	                    if let Some(qq) = er.quota.as_mut() {
1678	                        qq.exhausted = true;
1679	                    }
1680	                    er.status = "quota".into();
1681	                    let _ = write_record(rec_dir, &er);
1682	                    return 1;
1683	                }
1684	            }
1685	        }
1686	        match resume_once(&renv, rec_dir) {
1687	            Ok(status) => {
1688	                if status != "quota" {
1689	                    return exit_for(&status);
1690	                }
1691	            }
1692	            Err(why) => {
1693	                eprintln!("{TOOL}: resume of work run {} failed: {why}", rec.id);
1694	                return 1;
1695	            }
1696	        }
1697	    }
1698	}
1699	
1700	/// `--resume`/`--kick`: find the run and act. `--kick` wakes a sleeping detached run (or resumes a
1701	/// foreground quota run directly); `--resume` resumes a `quota`/`timeout` run here and now.
1702	fn resume_or_kick(o: &Options) -> i32 {
1703	    let (_repo_root, _collab, task_dir) = match prepare_paths(o) {
1704	        Ok(p) => p,
1705	        Err(why) => return refuse(&why),
1706	    };
1707	    let work_root = task_dir.join("work");
1708	    if o.kick {
1709	        return do_kick(o, &work_root);
1710	    }
1711	    let (rec_dir, rec) = match pick_run(&work_root, &o.id, &["quota", "timeout"]) {
1712	        Ok(x) => x,
1713	        Err(why) => return refuse(&why),
1714	    };
1715	    do_resume_foreground(o, &rec_dir, &rec)
1716	}
1717	
1718	fn do_kick(o: &Options, work_root: &Path) -> i32 {
1719	    let (rec_dir, rec) = match pick_run(work_root, &o.id, &["waiting_quota", "quota"]) {
1720	        Ok(x) => x,
1721	        Err(why) => return refuse(&why),
1722	    };
1723	    match rec.status.as_str() {
1724	        "waiting_quota" => {
1725	            if let Err(e) = std::fs::write(rec_dir.join(".kick"), b"1") {
1726	                return refuse(&format!("could not write the kick file ({e})"));
1727	            }
1728	            println!(
1729	                "{TOOL}: kicked work run {} - its sleeper will resume now.",
1730	                rec.id
1731	            );
1732	            0
1733	        }
1734	        "quota" => do_resume_foreground(o, &rec_dir, &rec),
1735	        other => refuse(&format!(
1736	            "work run {} is in state {other}, not waiting on a quota reset; --kick has nothing to wake.",
1737	            rec.id
1738	        )),
1739	    }
1740	}
1741	
1742	fn do_resume_foreground(o: &Options, rec_dir: &Path, rec: &RunRecord) -> i32 {
1743	    if rec.status != "quota" && rec.status != "timeout" {
1744	        return refuse(&format!(
1745	            "work run {} is in state {}, not quota or timeout; nothing to resume.",
1746	            rec.id, rec.status
1747	        ));
1748	    }
1749	    if rec.quota.as_ref().map(|q| q.exhausted).unwrap_or(false) {
1750	        return refuse(&format!(
1751	            "work run {} has spent its resume cap ({}); it needs a human.",
1752	            rec.id,
1753	            eff_max_resumes_rec(o, rec)
1754	        ));
1755	    }
1756	    let renv = match resume_env(o, rec, rec_dir) {
1757	        Ok(e) => e,
1758	        Err(why) => return refuse(&why),
1759	    };
1760	    match resume_once(&renv, rec_dir) {
1761	        Ok(status) => {
1762	            if status == "quota" {
1763	                let nrec = read_record(rec_dir).ok().flatten().unwrap_or_default();
1764	                foreground_quota(o, rec_dir, &nrec)
1765	            } else {
1766	                exit_for(&status)
1767	            }
1768	        }
1769	        Err(why) => refuse(&why),
1770	    }
1771	}
1772	
1773	/// Find the run to act on: when `id` narrows to exactly one, that run (whatever its status, so the
1774	/// caller can refuse with the state); otherwise the single run whose status is one of `want`.
1775	fn pick_run(work_root: &Path, id: &str, want: &[&str]) -> Result<(PathBuf, RunRecord), String> {
1776	    let id = id.trim().to_lowercase();
1777	    let mut all: Vec<(PathBuf, RunRecord)> = Vec::new();
1778	    // (0.2.4, F91-2) fail closed: enumeration and per-record inspection errors propagate.
1779	    // (0.2.4, F93-1) a dead owner's `died` transition goes through the locked display recovery.
1780	    for (_, dir) in record::run_dirs(work_root)? {
1781	        if let Some(rec) = record::read_for_display(work_root, &dir)? {
1782	            all.push((dir, rec));
1783	        }
1784	    }
1785	    if all.is_empty() {
1786	        return Err(format!(
1787	            "the task has no work run (under {})",
1788	            work_root.display()
1789	        ));
1790	    }
1791	    if !id.is_empty() {
1792	        let hits: Vec<_> = all
1793	            .into_iter()
1794	            .filter(|(_, r)| r.id.to_lowercase().starts_with(&id))
1795	            .collect();
1796	        return match hits.len() {
1797	            0 => Err(format!("no work run has an id starting with '{id}'")),
1798	            1 => Ok(hits.into_iter().next().unwrap()),
1799	            _ => Err(format!(
1800	                "'{id}' matches {} work runs; give a longer --id",
1801	                hits.len()
1802	            )),
1803	        };
1804	    }
1805	    let hits: Vec<_> = all
1806	        .into_iter()
1807	        .filter(|(_, r)| want.contains(&r.status.as_str()))
1808	        .collect();
1809	    match hits.len() {
1810	        0 => Err(format!(
1811	            "the task has no work run in state {} (give --id to target one)",
1812	            want.join(" or ")
1813	        )),
1814	        1 => Ok(hits.into_iter().next().unwrap()),
1815	        _ => Err(format!(
1816	            "the task has {} work runs in state {}; give --id to choose one",
1817	            hits.len(),
1818	            want.join(" or ")
1819	        )),
1820	    }
1821	}
