136	/// The `running` record's `args` of a detached run, as JSON (the background's options
137	/// wire; never a secret). Called by the module's `run` when it writes that record.
138	pub(super) fn wire_of(o: &Options, collab_root: &Path) -> String {
139	    let wire = WorkWire::of(o, &collab_root.to_string_lossy());
140	    serde_json::to_string(&wire).unwrap_or_default()
141	}
