143	/// The foreground of `--detach` once every guard passed and the `running` record (with the
144	/// wire) is on disk: spawn the background, print the come-back lines, exit 0. On a spawn
145	/// failure the record is removed and the caller sees exit 1.
146	pub fn start_detached(o: &Options, pre: &Prepared, id: &str, rec_dir: &Path) -> i32 {
147	    let log = rec_dir.join(".log");
148	    let exe = match std::env::current_exe() {
149	        Ok(e) => e,
150	        Err(e) => {
151	            let _ = std::fs::remove_file(rec_dir.join("run.json"));
152	            return refuse(&format!(
153	                "could not find this executable to start the background ({e}); nothing was started."
154	            ));
155	        }
156	    };
157	    let collab_abs = pre.collab_root.to_string_lossy().to_string();
158	    if let Err(e) = spawn_background(&exe, &o.task, &collab_abs, id, &log, &pre.repo_root) {
159	        let _ = std::fs::remove_file(rec_dir.join("run.json"));
160	        return refuse(&format!("{e}; nothing was started."));
161	    }
162	    let collab_for_cmd = (o.collab_dir != ".collab").then(|| collab_abs.clone());
163	    println!(
164	        "Detached work run {id}: it runs in the background ({} :: {} [{}]).",
165	        pre.provider,
166	        pre.model,
167	        pre.engine.as_str()
168	    );
169	    println!("record dir : {}", rec_dir.display());
170	    println!("console log: {}", log.display());
171	    println!(
172	        "come back  : c3 work --task {}{} --status --id {id} (exit 0 done, 1 died/timed out, 2 running); c3 work --task {}{} --wait --id {id} [--wait-timeout-sec <s>] waits until it is done",
173	        o.task,
174	        collab_for_cmd.as_deref().map(|c| format!(" --collab-dir \"{c}\"")).unwrap_or_default(),
175	        o.task,
176	        collab_for_cmd.as_deref().map(|c| format!(" --collab-dir \"{c}\"")).unwrap_or_default(),
177	    );
178	    0
179	}
