181	/// Spawn the background so it holds none of the caller's handles. On Windows this is the
182	/// consult detach's `CreateProcessW` (no inherited handles, its own hidden console so the
183	/// `>log` redirection works); elsewhere a plain spawn with the log on stdout/stderr.
184	#[cfg(windows)]
185	fn spawn_background(
186	    exe: &Path,
187	    task: &str,
188	    collab_abs: &str,
189	    id: &str,
190	    log: &Path,
191	    cwd: &Path,
192	) -> Result<(), String> {
193	    let exe_s = exe.to_string_lossy().to_string();
194	    let log_s = log.to_string_lossy().to_string();
195	    // cmd.exe would expand a %NAME% in these paths: refuse rather than corrupt.
196	    for p in [&exe_s, collab_abs, &log_s, id, task] {
197	        if p.contains('%') {
198	            return Err(format!(
199	                "--detach starts its background through cmd.exe, which would expand the '%' in '{p}'; run without --detach"
200	            ));
201	        }
202	    }
203	    let inner = format!(
204	        "\"{exe_s}\" work --task {task} --collab-dir \"{collab_abs}\" --detach-id {id} <NUL 1>\"{log_s}\" 2>&1"
205	    );
206	    let raw = format!("/d /v:off /s /c \"{inner}\"");
207	    let comspec = std::env::var("ComSpec").unwrap_or_else(|_| "cmd.exe".into());
208	    // SAFETY: the consult detach's straight CreateProcessW (bInheritHandles=FALSE, its own
209	    // hidden console); every pointer is to a local, NUL-terminated buffer.
210	    unsafe { crate::consult::detach::create_process_no_inherit(&comspec, &raw, cwd, None) }
211	}
212	
213	#[cfg(not(windows))]
214	fn spawn_background(
215	    exe: &Path,
216	    task: &str,
217	    collab_abs: &str,
218	    id: &str,
219	    log: &Path,
220	    cwd: &Path,
221	) -> Result<(), String> {
222	    let log_file = std::fs::File::create(log)
223	        .map_err(|e| format!("could not open the log file '{}' ({e})", log.display()))?;
224	    let log_err = log_file
225	        .try_clone()
226	        .map_err(|e| format!("could not open the log file ({e})"))?;
227	    let mut cmd = Command::new(exe);
228	    cmd.arg("work")
229	        .arg("--task")
230	        .arg(task)
231	        .arg("--collab-dir")
232	        .arg(collab_abs)
233	        .arg("--detach-id")
234	        .arg(id)
235	        .current_dir(cwd)
236	        .stdin(Stdio::null())
237	        .stdout(Stdio::from(log_file))
238	        .stderr(Stdio::from(log_err));
239	    #[cfg(unix)]
240	    {
241	        use std::os::unix::process::CommandExt;
242	        cmd.process_group(0);
243	    }
244	    cmd.spawn()
245	        .map(|_| ())
246	        .map_err(|e| format!("could not start the background process ({e})"))
247	}
