249	/// The background of `--detach-id <id>`: find the `running` record, take the wire, report
250	/// this process's pid, run the work child in this process and make the record final.
251	pub fn background(o: &Options) -> i32 {
252	    let rec_dir = match super::prepare_paths(o) {
253	        Ok(p) => p.2.join("work").join(&o.detach_id),
254	        Err(why) => return refuse(&why),
255	    };
256	    let mut rec = match read_record(&rec_dir) {
257	        Ok(Some(r)) => r,
258	        Ok(None) => {
259	            return refuse(&format!(
260	                "--detach-id is internal to --detach: there is no run.json in {}.",
261	                rec_dir.display()
262	            ))
263	        }
264	        Err(e) => return refuse(&format!("--detach-id is internal to --detach: {e}")),
265	    };
266	    if rec.status != "running" {
267	        return refuse(&format!(
268	            "--detach-id is internal to --detach: the work run {} is in state {}, not this process's.",
269	            rec.id, rec.status
270	        ));
271	    }
272	    let wire = rec.args.take().unwrap_or_default();
273	    let opts = match serde_json::from_str::<WorkWire>(&wire) {
274	        Ok(w) => w.into_options(),
275	        Err(e) => {
276	            rec.status = "refused".into();
277	            rec.ended = Some(iso_now());
278	            let _ = write_record(&rec_dir, &rec);
279	            return refuse(&format!(
280	                "the work run's recorded arguments are unusable: {e}"
281	            ));
282	        }
283	    };
284	    // (0.2.4, F89-1/F89-2) Claim the record under the task admission lock: write this background's
285	    // pid + start time (the liveness owner) and refuse if another run of the task went live in the
286	    // meantime, all BEFORE the child is spawned.
287	    let work_root = rec_dir.parent().map(Path::to_path_buf).unwrap_or_default();
288	    if let Err(e) = super::claim_start(&work_root, &rec_dir) {
289	        rec.status = "refused".into();
290	        rec.ended = Some(iso_now());
291	        let _ = write_record(&rec_dir, &rec);
292	        return refuse(&format!("the detached work run could not be claimed: {e}"));
293	    }
294	    println!(
295	        "{TOOL}: work run {} ({} :: {}) - pid {} on {}, started {}",
296	        rec.id,
297	        rec.provider,
298	        rec.model,
299	        std::process::id(),
300	        c3_core::host::machine_name(),
301	        iso_now()
302	    );
303	    super::run_prepared(&opts, &rec_dir, &rec.id, rec.seq, true)
304	}
