306	// ------------------------------------------------------------------ --status / --wait
307	
308	/// One work run as the query sees it.
309	struct WorkRun {
310	    id: String,
311	    record: Option<RunRecord>,
312	    error: String,
313	}
314	
315	fn read_runs(work_root: &Path) -> Vec<WorkRun> {
316	    // Status/--wait is a read-only listing (not the admission boundary): an enumeration failure
317	    // shows nothing, while a per-record inspection error is surfaced as that run's `error`.
318	    run_dirs(work_root)
319	        .unwrap_or_default()
320	        .into_iter()
321	        .map(|(_, dir)| {
322	            // (0.2.4, F93-1) the display path persists a dead owner's `died` only under the lock.
323	            let (record, error) = match read_for_display(work_root, &dir) {
324	                Ok(r) => (r, String::new()),
325	                Err(e) => (None, e),
326	            };
327	            let id = record.as_ref().map(|r| r.id.clone()).unwrap_or_else(|| {
328	                dir.file_name()
329	                    .unwrap_or_default()
330	                    .to_string_lossy()
331	                    .to_string()
332	            });
333	            WorkRun { id, record, error }
334	        })
335	        .collect()
336	}
337	
338	/// The exit code of a status listing: 2 while any run is running (or `waiting_quota`, a detached
339	/// run whose alarm sleeps until the quota window resets - the background is alive), else 1 when
340	/// one died/timed out/was refused/unreadable or is parked on `quota` (it needs a hand - a
341	/// `--resume`/`--kick`, exhausted or not), else 0 (an empty task is 0 too).
342	fn exit_of(runs: &[WorkRun]) -> i32 {
343	    for r in runs {
344	        let st = r
345	            .record
346	            .as_ref()
347	            .map(|x| x.status.as_str())
348	            .unwrap_or("unreadable");
349	        if super::record::is_pending(st) {
350	            return 2;
351	        }
352	    }
353	    for r in runs {
354	        let st = r
355	            .record
356	            .as_ref()
357	            .map(|x| x.status.as_str())
358	            .unwrap_or("unreadable");
359	        if st != "done" {
360	            return 1;
361	        }
362	    }
363	    0
364	}
365	
366	/// `--status` / `--wait`: read the task's work records only (no roster, no launcher, no
367	/// lock), print one block per run and return the exit code.
368	pub fn query(o: &Options) -> i32 {
369	    let (repo_root, _collab_root, task_dir) = match super::prepare_paths(o) {
370	        Ok(p) => p,
371	        Err(why) => return refuse(&why),
372	    };
373	    let _ = repo_root;
374	    let want = o.id.trim().to_lowercase();
375	    let work_root = task_dir.join("work");
376	    let select = |want: &str| -> Vec<WorkRun> {
377	        read_runs(&work_root)
378	            .into_iter()
379	            .filter(|r| want.is_empty() || r.id.to_lowercase().starts_with(want))
380	            .collect()
381	    };
382	    let mut runs = select(&want);
383	    if !want.is_empty() && runs.is_empty() {
384	        let known: Vec<String> = read_runs(&work_root).into_iter().map(|r| r.id).collect();
385	        return refuse(&format!(
386	            "no work run of task '{}' has an id starting with '{want}' ({}).",
387	            o.task,
388	            if known.is_empty() {
389	                "it has none".to_string()
390	            } else {
391	                format!("its work runs: {}", known.join(", "))
392	            }
393	        ));
394	    }
395	    if o.wait {
396	        if o.wait_timeout_sec_given && o.wait_timeout_sec <= 0 {
397	            return refuse(&format!(
398	                "--wait-timeout-sec must be greater than 0 (got {}); leave it out for the run's own timeout.",
399	                o.wait_timeout_sec
400	            ));
401	        }
402	        let limit = if o.wait_timeout_sec > 0 {
403	            o.wait_timeout_sec
404	        } else {
405	            runs.iter()
406	                .filter(|r| {
407	                    r.record
408	                        .as_ref()
409	                        .map(|x| super::record::is_pending(&x.status))
410	                        .unwrap_or(false)
411	                })
412	                .filter_map(|r| r.record.as_ref().map(|x| x.timeout_sec))
413	                .max()
414	                .filter(|t| *t > 0)
415	                .unwrap_or(3600)
416	        };
417	        let waiting: Vec<String> = runs.iter().map(|r| r.id.clone()).collect();
418	        println!(
419	            "{TOOL}: waiting for {} work run{} of task '{}' - up to {limit} s, checking every 2 s",
420	            waiting.len(),
421	            if waiting.len() != 1 { "s" } else { "" },
422	            o.task
423	        );
424	        let watch = std::time::Instant::now();
425	        loop {
426	            runs = select(&want);
427	            let still = runs.iter().any(|r| {
428	                r.record
429	                    .as_ref()
430	                    .map(|x| super::record::is_pending(&x.status))
431	                    .unwrap_or(false)
432	            });
433	            if !still || watch.elapsed().as_secs() >= limit as u64 {
434	                break;
435	            }
436	            std::thread::sleep(std::time::Duration::from_secs(2));
437	        }
438	    }
439	    if runs.is_empty() {
440	        println!(
441	            "{TOOL}: no work run in task '{}' ({}).",
442	            o.task,
443	            work_root.display()
444	        );
445	        return 0;
446	    }
447	    let mut first = true;
448	    for r in &runs {
449	        if !first {
450	            println!();
451	        }
452	        first = false;
453	        let Some(rec) = &r.record else {
454	            println!("work {}: unreadable ({})", r.id, r.error);
455	            continue;
456	        };
457	        println!(
458	            "work {} ({}/{} [{}]): {} (started {}{}, exit {})",
459	            rec.id,
460	            rec.provider,
461	            rec.model,
462	            rec.engine,
463	            rec.status,
464	            rec.started,
465	            rec.ended
466	                .as_deref()
467	                .map(|e| format!(", ended {e}"))
468	                .unwrap_or_default(),
469	            rec.exit_code
470	                .map(|c| c.to_string())
471	                .unwrap_or_else(|| "(none)".into())
472	        );
473	        let turns = rec
474	            .turns
475	            .map(|t| t.to_string())
476	            .unwrap_or_else(|| "(none)".into());
477	        let tools = if rec.tool_calls.is_empty() {
478	            String::new()
479	        } else {
480	            format!(
481	                "; tool calls {}",
482	                rec.tool_calls
483	                    .iter()
484	                    .map(|(k, v)| format!("{k} x{v}"))
485	                    .collect::<Vec<_>>()
486	                    .join(", ")
487	            )
488	        };
489	        println!("  turns {turns}{tools}");
490	        if rec.files_changed.is_empty() {
491	            println!("  files changed: (none)");
492	        } else {
493	            println!("  files changed: {}", rec.files_changed.join(", "));
494	        }
495	        if !rec.role.is_empty() {
496	            let of = if rec.of.is_empty() {
497	                "the working tree".to_string()
498	            } else {
499	                rec.of.clone()
500	            };
501	            println!("  role {} of {of}", rec.role);
502	        }
503	        if !rec.scope_violations.is_empty() {
504	            println!("  OUT OF SCOPE: {}", rec.scope_violations.join(", "));
505	        }
506	        if let Some(q) = &rec.quota {
507	            if rec.status == "waiting_quota" {
508	                // (0.2.4, F89-6) The persisted cap, unless the operator overrode it on this call.
509	                let max = if o.max_resumes > 0 {
510	                    o.max_resumes
511	                } else if rec.max_resumes > 0 {
512	                    rec.max_resumes
513	                } else {
514	                    super::MAX_RESUMES_DEFAULT
515	                };
516	                println!(
517	                    "  waiting_quota until {} (resume {}/{})",
518	                    local_of(&q.resume_at),
519	                    q.resumes,
520	                    max
521	                );
522	            }
523	            println!(
524	                "  quota: {} (resumes {}{}; resume_at {})",
525	                q.text,
526	                q.resumes,
527	                if q.exhausted { ", exhausted" } else { "" },
528	                q.resume_at
529	            );
530	        }
531	    }
532	    exit_of(&runs)
533	}
