                "work",
                "--task",
                "t",
                "--brief",
                &brief,
                "--provider",
                "ZAI-claude",
            ],
            &env,
        )
        .spawn()
        .expect("spawn c3");

    let run_json = e.work_root().join("01-ZAI-claude-glm-5.3").join("run.json");
    let mut ok = false;
    for _ in 0..200 {
        if run_json.is_file() {
            if let Ok(v) = serde_json::from_str::<Value>(&read(&run_json)) {
                if v["status"] == "running" && v["pid"].as_i64().unwrap_or(0) > 0 {
                    ok = true;
