    /// path separators and suffixed shells refused, plain exes and whitelisted bare tools allowed.
    #[test]
    fn validate_allow_pattern_grammar() {
        for bad in [
            "Bash",
            "Bash(python:*)",
            "Bash(powershell.exe:*)",
            "Bash(C:\\x\\node.exe:*)",
            "Bash(*)",
            "Bash(python -c:*)",
        ] {
            assert!(
                validate_allow_pattern(bad).is_err(),
