            "  echo '{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"num_turns\":2,\"result\":\"Resumed and finished; cargo test: 12 passed.\",\"usage\":{\"input_tokens\":8,\"output_tokens\":4}}'\n",
